WITH payload AS (SELECT $archive_payload$[{"id":"b8518d57-93d0-5c31-acdb-2710837b1b7a","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -رد مسروق -انقضاء الدعوى العامة وصدور احلكم النهائي -احلكم بصرف النظر لعدم االختصاص النوعي .","document_number":"34264142","case_number":"34278510","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/15","year":"1434","subject":"اختصاص -رد مسروق -انقضاء الدعوى العامة وصدور احلكم النهائي -احلكم بصرف النظر لعدم االختصاص النوعي .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1434/3/15 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪34264142 :‬‬\n                          ‫َر ْق ُم الدعوى‪34278510:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                 ‫‪ 34280253‬تاريخه‪1434/7/26:‬هـ‬\n\n\n      ‫اختصــاص ‪ -‬رد مســروق ‪ -‬انقضــاء الدعــوى العامــة وصــدور احلكــم‬\n           ‫النهائــي ‪ -‬احلكــم بصــرف النظــر لعــدم االختصــاص النوعــي ‪.‬‬\n\n\n\n\n                        ‫‪ -1‬املواد (‪ )184-47‬من نظام املرافعات الشرعية‪.‬‬\n      ‫‪ -2‬خطاب معالي وزير العدل رقم (‪ )2317/829‬وتاريخ ‪1423/2/22‬هـ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي علــى املدعــى عليــه مببلــغ مالــي نظيــر حقــه اخلــاص‬\n      ‫الناشــئ عــن قضيــة ســرقة صــدر فيهــا حكــم نهائــي للحق العــام‪ -‬قررت‬\n      ‫احملكمــة اجلزائيــة إحالــة القضيــة إلــى احملكمــة العامــة لكــون املبلــغ‬\n      ‫املطالــب بــه يفــوق اختصاصهــا القيمــي فتكــون غيــر مختصــة بنظرهــا‬\n      ‫وتختــص بهــا احملكمــة العامــة‪ -‬أعيــدت القضيــة مــن احملكمــة العامــة‬\n      ‫إلــى احملكمــة اجلزائيــة لكــون احلكــم يف احلــق العــام صــادر منهــا‪ -‬مــن‬\n      ‫املقــرر نظام ـ ًا أنــه إذا انقضــت الدعــوى العامــة بصــدور حكــم نهائــي‬\n      ‫ثــم رفعــت الدعــوى اخلاصــة بعــد ذلــك فيكــون نظرهــا لــدى احملكمــة‬\n      ‫املختصــة نوعـ ًا ومكانـاً‪ -‬قضــت احملكمــة بصــرف النظــر عــن دعــوى‬\n      ‫املدعــي لعــدم االختصــاص‪ -‬قــررت محكمــة االســتئناف املصادقــة‬\n                                                                       ‫علــى احلكــم‪.‬‬\n\n‫‪243‬‬\n\f‫احلمــد هلل وحــده وبعــد ففــي هــذا اليــوم االثنــن املوافــق ‪1434/07/10‬هـ‬\n‫لــدي أنــا رئيــس احملكمــة اجلزائيــة بحائــل والقائــم بعمــل فضيلــة‬\n‫القاضــي أثنــاء تكليفــه مــن قبــل وزارة العــدل بــدورة تدريبيــة باملعهــد‬\n‫العالــي للقضــاء ملــدة شــهرين ومتتعــه بإجــازة اعتياديــة ملــدة شــهر واحــد‬\n‫وفيهــا افتتحــت اجللســة الســاعة العاشــرة صباح ـ ًا للنظــر يف الدعــوى‬\n‫املقامــة مــن‪ ......./‬ســعودي بالســجل املدنــي رقــم(‪ ).........‬ضــد مكفولــه‬\n‫املقيــم‪ ......./‬ســوداني اجلنســية مبوجــب رخصــة االقامــة رقــم(‪ ).....‬وذلــك‬\n‫يف احلــق اخلــاص وحيــث قــرر املدعــي باحلــق اخلــاص أنــه يطالــب املدعــى‬\n‫وبناء على‬\n       ‫عليــه مببلــغ أربعم ــ‪400,000‬ـ ــائة ألــف ريال نظير حقــه اخلاص ً‬\n‫املــادة(‪ )32‬مــن نظــام املرافعــات الشــرعية مت إحالتهــا للمحكمــة العامــة‬\n‫بحائــل باخلطــاب رقــم (‪ )341463752‬وتاريــخ ‪1434/06/19‬ه ـ لعــدم‬\n‫االختصــاص‪ ،‬وبإحالتهــا لفضيلــة القاضــي باحملكمــة العامــة بحائــل‬\n‫أعادهــا لنــا بخطابــه رقــم ‪ 341463752‬يف ‪1434/06/26‬ه ـ واملتضمــن‬\n‫(أنهــا مــن اختصــاص احملكمــة اجلزائيــة بحائــل وفق ـ ًا للمــادة(‪)148‬‬\n‫مــن نظــام املرافعــات الشــرعية وعليــه أجيــب مبــا يلــي‪ -:‬أو ًال إن املــادة‬\n‫(‪ )148‬مــن نظــام املرافعــات الشــرعية نصــت (أن مــن حلقــه ضــرر مــن‬\n‫اجلرميــة ولوارثــه مــن بعــده أن يطالــب بحقــه اخلــاص مهمــا بلــغ مقــداره‬\n‫أمــام احملكمــة املنظــورة أمامهــا الدعــوى اجلزائيــة يف أي حــال كانــت‬\n‫عليهــا الدعــوى) فاالختصــاص املذكــور مقيــد بكــون الدعــوى اجلزائية‬\n‫منظــورة‪ ،‬والدعــوى اجلزائيــة يف هــذه القضيــة قــد انتهــت قبــل تقــدمي‬\n‫هــذه الدعــوى اخلاصــة بالقــرار الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n\n                                                                                    ‫‪244‬‬\n\f      ‫اجلزائيــة بحائــل ‪ ...‬برقــم (‪ )34199286‬وتاريــخ ‪1434/04/28‬هــ‪ ،‬ثانيـ ًا‬\n      ‫وجــه معالــي وزيــر العــدل بالنيابــة فضيلــة رئيــس احملكمــة العامــة‬\n      ‫بالريــاض بخطابــه رقــم(‪ )2317/829‬بتاريــخ ‪1423/02/22‬ه ـ بشــأن‬\n      ‫(‪ )148‬مــن نظــام املرافعــات الشــرعية ( بأنــه إذا انقضــت الدعــوى العامة‬\n      ‫بصــدور حكــم نهائــي ثــم رفعــت الدعــوى اخلاصــة بعــد ذلــك فيكــون‬\n      ‫ـاء‬\n        ‫نظرهــا لــدى احملكمــة املختصــة نوعـ ًا ومكانـاً) وملــا تقــدم كلــه وبنـ ً‬\n      ‫علــى املــادة (‪ )74‬مــن نظــام املرافعــات الشــرعية ولوائحــه التنفيذيــة فقــد‬\n      ‫صرفــت النظــر عــن هــذه الدعــوى لعــدم االختصــاص بهــا وإمنــا هــي مــن‬\n      ‫اختصــاص احملكمــة العامــة بحائــل وأمــرت برفــع كامــل أوراق املعاملة‬\n      ‫حملكمــة االســتئناف للفصــل يف ذلــك وبــاهلل التوفيــق وصلــى اهلل علــى‬\n             ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/07/10‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده وبعــد ‪ ..‬فقــد اطلعنــا نحــن قضــاة الدائــرة احلقوقيــة‬\n      ‫األولــى لتدقيــق القضايــا احلقوقيــة مبحكمــة االســتئناف مبنطقــة‬\n      ‫حائــل علــى املعاملــة الــواردة مــن رئيــس احملكمــة اجلزائيــة بحائــل‬\n      ‫برقــم ‪ 341463752‬وتاريخ‪1434/07/11‬ه ـ واملقيــدة لدينــا‬\n      ‫بتاريــخ ‪1434/07/11‬ه ـ املرفــق بهــا القــرار رقــم ‪34264142‬يف‬\n      ‫‪1434/07/10‬ه ـ الصــادر مــن فضيلتكــم اخلــاص بدعــوى ‪ .....‬ضــد‬\n      ‫مكفولــة املقيــم ‪......... /‬ســوداني اجلنســية بشــأن املطالبــة بــرد مســروق‬\n      ‫علــى الصفــة املوضحــة يف القــرار وقــد تضمــن القــرار حكــم فضيلتــه‬\n      ‫كمــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه وأوراق‬\n      ‫املعاملــة ‪ :‬جــرت املصادقــة علــى مــا حكــم بــه فضيلتــه بــأن نظــر هــذه‬\n      ‫الدعــوى مــن اختصــاص احملكمــة العامــة بحائــل مــع تنبيــه فضيلتــه إلــى‬\n      ‫إفهــام األطــراف بذلــك حســب التعليمــات واهلل املوفــق وصلــى اهلل وســلم‬\n                                             ‫علــى نبينــا محمــد وعلــى آلــه وصحبــه‪.‬‬\n‫‪245‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":243,"source_page_end":245,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"024c59539a9c6d8e015e262c337f803107baa4eee5224c8ce6c5907a8a8e7f6e","normalized_text_hash":"935736551431b25b8700a977af0b07e348051e263acc034ac68a3370e5fafd62","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p243-34264142"},{"id":"bd899577-db4d-59b1-8b90-84484417e69f","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -قسمة تركة -دفع بوجود دعوى سابقة لذات الدعوى املاثلة مرتبطة معها موضوع ا وسبب ا يف محكمة أخرى وطلب اإلحالة إلى المحكمة األخيرة -الدفع بإحالة الدعوى إلى محكمة أخرى لقيام ذات النزاع أمامها يجب إبداؤه قبل أي طلب أو دفاع يف الدعوى -عدم جواز نقل أي قضية رفعت بطريقة صحيحة حملكمة مختصة إلى محكمة أو جهة أخرى قبل احلكم فيها -احلكم بعدم االختصاص ال يكون إال بعد حتقق التدافع -حتقق التدافع -صرف","document_number":"34322311","case_number":"33635321","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/9/17","year":"1434","subject":"اختصاص -قسمة تركة -دفع بوجود دعوى سابقة لذات الدعوى املاثلة مرتبطة معها موضوع ا وسبب ا يف محكمة أخرى وطلب اإلحالة إلى المحكمة األخيرة -الدفع بإحالة الدعوى إلى محكمة أخرى لقيام ذات النزاع أمامها يجب إبداؤه قبل أي طلب أو دفاع يف الدعوى -عدم جواز نقل أي قضية رفعت بطريقة صحيحة حملكمة مختصة إلى محكمة أو جهة أخرى قبل احلكم فيها -احلكم بعدم االختصاص ال يكون إال بعد حتقق التدافع -حتقق التدافع -صرف","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34322311 :‬تاريخه‪1434/9/17 :‬هـ‬\n                  ‫رقم الدعوى‪33635321 :‬‬\n             ‫رقم قرار التصديق من محكمة‬\n ‫االستئناف‪ 35112444:‬تاريخه‪1435/1/11 :‬هـ‬\n\n\n‫اختصــاص ‪ -‬قســمة تركــة‪ -‬دفــع بوجــود دعــوى ســابقة لــذات الدعــوى‬\n‫املاثلــة مرتبطــة معهــا موضوع ـ ًا وســبب ًا يف محكمــة أخــرى وطلــب‬\n‫اإلحالــة إلــى احملكمــة األخيــرة‪ -‬الدفــع بإحالــة الدعــوى إلــى محكمــة‬\n‫أخــرى لقيــام ذات النــزاع أمامهــا يجــب إبــداؤه قبــل أي طلــب أو دفــاع يف‬\n‫الدعــوى‪ -‬عــدم جــواز نقــل أي قضيــة رفعــت بطريقــة صحيحــة حملكمــة‬\n‫مختصــة إلــى محكمــة أو جهــة أخــرى قبــل احلكــم فيهــا‪ -‬احلكــم بعــدم‬\n‫االختصــاص ال يكــون إال بعــد حتقــق التدافــع‪ -‬حتقــق التدافــع‪ -‬صــرف‬\n                                ‫النظــر عــن الدعــوى لعــدم االختصــاص ‪.‬‬\n\n\n\n\n                                  ‫‪ .1‬املادة ‪ 11‬من نظام املرافعات الشرعية‪.‬‬\n      ‫‪ .2‬املادة ‪ 2/71‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n    ‫‪ .3‬املادة ‪ 2-1/74‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n‫حضــر املدعــي وكالــة ولــم يحضــر املدعــى عليهــم وحضــرت عمــة‬\n‫املدعــى عليهــم وقــررت قائلــة بــأن هنــاك دعــوى ســابقة لهــذه الدعــوى‬\n‫بخصــوص تركــة املــورث ‪ ....‬محالــة ألحــد املكاتــب القضائيــة وتطلــب‬\n‫إحالــة هــذه الدعــوى لســابقتها بنــاء علــى املــادة ‪ 71‬و ‪ 2/71‬مــن نظــام‬\n\n                                                                                  ‫‪246‬‬\n\f      ‫املرافعــات الشــرعية ‪ -‬وبعرضــه علــى املدعــي وكالــة قــال ‪ :‬تلــك دعــوى‬\n      ‫إنهائيــة لقســمة تركــة املــورث ‪ ،‬وهــذه دعــوى حقوقيــة لقســمة تركــة‬\n      ‫املــورث ‪ ،‬ويطلــب الســير يف الدعــوى ‪ -‬قــرر ناظــر القضية إحالة الدعوى‬\n      ‫لســابقتها املقيــدة بأحــد املكاتــب القضائيــة بنــاء علــى املــادة ‪ 71‬مــن‬\n      ‫نظــام املرافعــات الشــرعية ونصهــا (الدفــع ببطــان صحيفــة الدعــوى‬\n      ‫أو بعــدم االختصــاص احمللــي أو بإحالــة الدعــوى إلــى محكمــة أخــرى‬\n                     ‫لقيــام النــزاع ذاتــه أمامهــا أو لقيــام دعــوى أخــرى مرتبطــة ‪)..‬‬\n      ‫واملــادة ‪ 2/71‬مــن ذات النظــام ‪ ،‬ثــم عــادت املعاملــة مــن القاضي بخطاب‬\n      ‫تضمــن (أنــه قــد انتهــى تكليفــه بالعمــل يف اإلنهــاءات وهــذا اإلنهــاء قــد‬\n                         ‫أحيــل إلــى صحائــف الدعــوى إلحالتــه حســب اإلحــاالت ‪..‬‬\n      ‫وبنــاء علــى ذلــك فليــس لــدي ســابقة) ا‪.‬هــ‪ ،‬وبالرجــوع للنظــام الشــامل‬\n      ‫تبــن أن اإلنهــاء ال زال لديــه ‪ ،‬ولــم يتــم إحالتــه إلــى أي جهــة أخــرى ‪،‬‬\n      ‫وبنــاء علــى املــادة ‪ 11‬مــن نظــام املرافعــات الشــرعية ‪ ،‬والتــي تنــص علــى‬\n      ‫(ال يجــوز نقــل أي قضيــة رفعــت بطريقــة صحيحــة حملكمــة مختصــة‬\n      ‫إلــى محكمــة أو جهــة أخــرى قبــل احلكــم فيهــا) ‪ ،‬وانتهــاء تكليــف‬\n      ‫فضيلتــه يف العمــل يف الدوائــر اإلنهائيــة ال مينعــه مــن إكمــال مــا أحيــل‬\n      ‫لــه يف وقتــه ‪ ،‬ولكــن ال تتــم إحالــة معاملــة إنهائيــة جديــدة لــه ‪ ،‬فضــا‬\n      ‫عــن كــون املعاملــة بعينهــا ال زالــت يف مكتبــه بحســب مــا هــو مــدون يف‬\n      ‫النظــام الشــامل‪ ،‬وبنــاء علــى املــادة ‪ 71‬مــن نظــام املرافعــات الشــرعية‬\n      ‫واملــادة ‪ 2/71‬مــن ذات النظــام ‪ ،‬ولــم حتــدد املــادة أنــه يجــب أن ال تكــون‬\n      ‫الســابقة دعــوى إنهائيــة والالحقــة دعــوى حقوقيــة بــل أطلقــت احلكــم‬\n      ‫ولــم تخصــص بذلــك ‪ ،‬فهــي باقيــة علــى عمومهــا ‪ ،‬وبنــاء علــى املــادة‬\n      ‫‪ 1/74‬مــن ذات النظــام ‪ ،‬وبنــاء علــى املــادة ‪ 2/74‬مــن ذات النظــام ‪-‬‬\n\n\n‫‪247‬‬\n\f‫وحيــث حتقــق التدافــع ‪ -‬ملــا تقــدم صــدر احلكــم بصــرف النظــر عــن‬\n‫دعــوى املدعــي لعــدم االختصــاص ‪ -‬بعــث املعاملــة حملكمــة االســتئناف‬\n‫لتدقيــق احلكــم ‪ -‬صــدق احلكــم من الدائــرة احلقوقية الثانية مبحكمة‬\n                                   ‫االســتئناف مبنطقــة مكــة املكرمــة‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جدة‪/‬املســاعد برقــم ‪ 33635321‬وتاريــخ‬\n‫‪1433/11/02‬ه ـ املقيــدة باحملكمــة برقــم ‪ 331940091‬وتــاري ـ ــخ‬\n‫‪1433/11/02‬هـ ففي ي ـ ـ ــوم األح ـ ـ ــد املوافق ‪1434/04/21‬هـ افتتحت‬\n‫اجللســة الــساع ـ ـ ـ ــة ‪ 09 : 30‬وفيها حضر ‪.........‬ســعودي اجلنســية مبوجب‬\n‫الســجل املدنــي رقــم ‪.........‬بصفتــه وكيــا عــن ‪ .........‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪.........‬مبوجــب الوكالــة الصــادرة مــن‬\n‫كتابــة العــدل الثانيــة شــمال محافظــة جــدة برقــم ‪ 34136729‬وتاريــخ‬\n‫‪1434/2/5‬ه ـ ولــم يحضــر املدعــى عليهــم ورثــة ‪.........‬وال مــن ميثلهــم ‪،‬‬\n‫ولــم يردنــا مــا يفيــد تبليغهــم‪ ،‬وحضــرت ‪.........‬ســعودية اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪.........‬بصفتهــا عمــة بعــض املدعــى عليهــم أوالد‬\n‫‪ ،.........‬وقــررت قائلــة ‪ :‬إن هنــاك دعــوى ســابقة لهــذه الدعــوى بخصوص‬\n‫تركــة املــورث ‪ ،.........‬مقيــدة برقــم ‪.........‬وتاريــخ ‪1433/8/13‬ه ـ لــدى‬\n‫القاضــي الشــيخ ‪.........‬باملكتــب القضائــي رقــم ‪ ، 12‬وأطلــب إحالــة‬\n‫هــذه الدعــوى لســابقتها بنــاء علــى املــادة ‪ 71‬و ‪ 2/71‬مــن نظــام املرافعــات‬\n‫الشــرعية ‪ .‬وبعرضــه علــى املدعــي وكالــة قــال ‪ :‬تلــك دعــوى إنهائيــة‬\n\n                                                                                    ‫‪248‬‬\n\f      ‫لقســمة تركــة املــورث ‪ ،‬وهــذه دعــوى حقوقيــة لقســمة تركــة املــورث ‪،‬‬\n      ‫وأطلــب الســير يف الدعــوى لــدى فضيلتكــم ‪ .‬وعليــه فقــد قــررت إحالــة‬\n      ‫الدعــوى لســابقتها املقيــدة برقــم ‪ 331528529‬وتاريــخ ‪1433/8/13‬ه ـ‬\n      ‫لــدى القاضــي الشــيخ‪ .........‬باملكتــب القضائــي رقــم ‪ ...‬بنــاء علــى املــادة‬\n      ‫‪ 71‬مــن نظــام املرافعــات الشــرعية ونصهــا (الدفــع ببطــان صحيفــة‬\n      ‫الدعــوى أو بعــدم االختصــاص احمللــي أو بإحالــة الدعــوى إلــى محكمــة‬\n      ‫أخــرى لقيــام النــزاع ذاتــه أمامهــا أو لقيــام دعــوى أخــرى مرتبطــة بهــا‬\n      ‫يجــب إبــداؤه قبــل أي طلــب أو دفــاع يف الدعــوى ‪ ،‬وإال ســقط احلــق‬\n      ‫فيمــا لــم يبــد منهــا) واملــادة ‪ 2/71‬مــن ذات النظــام ‪ ،‬ونصهــا (االرتبــاط‬\n      ‫يف هــذه املــادة هــو‪ :‬اتصــال الدعــوى الالحقــة بالســابقة يف املوضــوع أو‬\n                                            ‫الســبب وال يلــزم احتادهمــا يف املقــدار) ‪.‬‬\n                                                     ‫وأقفلت اجللسة الساعة ‪. 10 : 00‬‬\n      ‫ويف يــوم اخلميــس املوافــق‪ 1434/09/10‬ه ـ افتتحــت اجللســة الســاعة‬\n      ‫‪ 12 : 00‬وفيهــا قــد عــادت لنــا املعاملــة مــن القاضــي ‪.........‬بخطابــه‬\n      ‫رقــم ‪ 331940091‬وتاريــخ ‪1434/8/10‬ه ـ واملتضمــن (أنــه قــد انتهــى‬\n      ‫تكليفنــا بالعمــل يف اإلنهــاءات وهــذا اإلنهــاء قــد أحيــل إلــى صحائــف‬\n      ‫الدعــوى إلحالتــه حســب اإلحــاالت ‪ ،‬وحيــث تقدمــوا بدعــوى حقوقيــة‬\n      ‫أحيلــت إلــى املكتــب القضائــي الســابع بهــذا القيــد وقــد حــدد لهــم‬\n      ‫موعــد ونظرهــا فضيلــة الشــيخ ‪.........‬لــذا نأمــل إعادتهــا للمكتــب‬\n      ‫الســابع ألننــي ليــس لــي واليــة يف اإلنهــاءات بعــد انتهــاء تكليفنــا بالعمــل‬\n      ‫فيهــا وبنــاء علــى ذلــك فليــس لــدي ســابقة) ‪ ،‬وبالرجــوع للنظــام الشــامل‬\n      ‫تبــن أن اإلنهــاء ال زال لديــه ‪ ،‬ولــم يتــم إحالتــه إلــى أي جهــة أخــرى‬\n      ‫(مرفــق صــورة مــن النظــام الشــامل) ‪ ،‬وبنــاء علــى املــادة ‪ 11‬مــن نظــام‬\n\n\n‫‪249‬‬\n\f‫املرافعــات الشــرعية ‪ ،‬والتــي تنــص علــى (ال يجــوز نقــل أي قضيــة رفعــت‬\n‫بطريقــة صحيحــة حملكمــة مختصــة إلــى محكمــة أو جهــة أخــرى قبــل‬\n‫احلكــم فيهــا) ‪ ،‬فقــد قضــت بعــدم جــواز نقــل القضيــة إذا رفعت بطريقة‬\n‫صحيحــة حملكمــة مختصــة قبــل احلكــم فيهــا ‪ ،‬وانتهــاء تكليــف‬\n‫فضيلــة يف العمــل يف الدوائــر اإلنهائيــة ال مينعــه مــن إكمــال مــا أحيــل‬\n‫لــه يف وقتــه ‪ ،‬ولكــن ال تتــم إحالــة معاملــة إنهائيــة جديــدة لــه ‪ ،‬فضــا‬\n‫عــن كــون املعاملــة بعينهــا ال زالــت يف مكتبــه بحســب مــا هــو مــدون يف‬\n‫النظــام الشــامل ‪ ،‬وبنــاء علــى املــادة ‪ 71‬مــن نظــام املرافعــات الشــرعية‬\n‫ونصهــا (الدفــع ببطــان صحيفــة الدعــوى أو بعــدم االختصــاص احمللــي‬\n‫أو بإحالــة الدعــوى إلــى محكمــة أخــرى لقيــام النــزاع ذاتــه أمامهــا أو‬\n‫لقيــام دعــوى أخــرى مرتبطــة بهــا يجــب إبــداؤه قبــل أي طلــب أو دفــاع يف‬\n‫الدعــوى ‪ ،‬وإال ســقط احلــق فيمــا لــم يبــد منهــا) واملــادة ‪ 2/71‬مــن ذات‬\n‫النظــام ‪ ،‬ونصهــا (االرتبــاط يف هــذه املــادة هــو‪ :‬اتصــال الدعوى الالحقة‬\n‫بالســابقة يف املوضــوع أو الســبب وال يلــزم احتادهمــا يف املقــدار) ‪ ،‬ولــم‬\n‫حتــدد املــادة أنــه يجــب أن ال تكــون الســابقة دعــوى إنهائيــة والالحقــة‬\n‫دعــوى حقوقيــة بــل أطلقــت احلكــم ولــم تخصــص بذلــك ‪ ،‬فهــي باقيــة‬\n‫علــى عمومهــا ‪ ،‬وبنــاء علــى املــادة ‪ 1/74‬مــن ذات النظــام ‪ ،‬ونصهــا (ال‬\n‫يحكــم القاضــي بعــدم االختصــاص إال بعــد حتقــق التدافــع) ‪ ،‬وبنــاء‬\n‫علــى املــادة ‪ 2/47‬مــن ذات النظــام ‪ ،‬ونــص احلاجــة منهــا (إذا كان‬\n‫التدافــع بــن قضــاة احملكمــة الواحــدة‪ ،‬أو بــن رئيــس احملكمــة وأحــد‬\n‫قضاتهــا ‪ ،‬أو بــن محكمتــن تابعتــن جلهــة قضائيــة واحــدة ‪ ،‬فعلــى‬\n‫مــن أحيلــت إليــه أو ًال ‪ ،‬ثــم أعيــدت إليــه ثاني ـ ًا ولــم يقتنــع باختصاصــه‬\n‫بهــا أن يصــدر قــرار ًا بصــرف النظــر بعــدم اختصاصــه ‪ ،‬وعليــه أن يرفــع‬\n\n\n                                                                                      ‫‪250‬‬\n\f      ‫القــرار وصــورة ضبطــه وأوراق املعاملــة إلــى محكمــة التمييــز؛ للفصــل‬\n      ‫يف ذلــك ‪ ،‬ومــا تقــرره يلــزم العمــل بــه) ‪ ،‬وحيــث حتقــق التدافــع بينــي‬\n      ‫وبــن فضيلــة القاضــي الشــيخ ‪ .........‬باملكتــب القضائــي رقــم ‪ ...‬لذلــك‬\n      ‫كلــه ‪ ،‬فقــد حكمــت بصــرف النظــر عــن دعــوى املدعــي ‪.........‬لعــدم‬\n      ‫االختصــاص ‪ ،‬وأن االختصــاص منعقــد لفضيلــة القاضــي الشــيخ ‪.........‬‬\n      ‫باملكتــب القضائــي رقــم ‪ ....‬لوجــود دعــوى ســابقة لديــه مقيــدة برقــم‬\n      ‫‪ 331528529‬وتاريــخ ‪1433/8/13‬ه ـ ‪ .‬وبــه حكمــت ‪ .‬وقــررت بعــث‬\n      ‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪ .‬وأقفلــت اجللســة الســاعة‬\n      ‫‪ . 12 : 30‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                      ‫وصحبــه وســلم ‪ .‬حــرر يف ‪1434/09/10‬ه ـ ‪.‬‬\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد ‪ ،‬فقــد‬\n      ‫جــرى منــا نحــن قضــاة الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n      ‫يف منطقــة مكــة املكرمــة االطــاع علــى املعاملــة الــواردة مــن فضيلــة‬\n      ‫رئيــس احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 331940091‬وتاريــخ‬\n      ‫‪1435/1/1‬ه ـ املرفــق بهــا الصــك الصــادر مــن فضيلــة الشــيخ ‪.........‬‬\n      ‫القاضــي باحملكمــة العامــة مبحافظــة جــدة برقــم ‪ 34322311‬وتاريــخ‬\n      ‫‪1434/9/17‬ه ـ ‪ ،‬املتضمــن دعــوى ‪.........‬ضــد ‪ ،.........‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه تقــرر املوافقــة علــى احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل‬\n                              ‫وســلم علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪251‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":246,"source_page_end":251,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"17e404c135e0f9d5d1943d56663355ed881661ed6367ade763b891a3368b1279","normalized_text_hash":"2076453a48fe812cb9d50944be16f37c3694929255900c088757b660542614c9","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p246-34322311"},{"id":"6b17966b-69d9-5aea-bd3f-e7cb1aabbe1a","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -قسمة تركة -مطالبة الورثة ببيع ممتلكات املورث باملزاد العلني وتقسيمها عليهم -تعدد املدعى عليهم وإقامة األكثرية خارج نطاق اختصاص المحكمة -االختصاص للمحكمة التي يقع يف نطاقها محل إقامة األكثرية حال تعدد املدعى عليهم -صرف النظر عن الدعوى لعدم االختصاص املكاني .","document_number":"34377323","case_number":"34506737","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/3","year":"1434","subject":"اختصاص -قسمة تركة -مطالبة الورثة ببيع ممتلكات املورث باملزاد العلني وتقسيمها عليهم -تعدد املدعى عليهم وإقامة األكثرية خارج نطاق اختصاص المحكمة -االختصاص للمحكمة التي يقع يف نطاقها محل إقامة األكثرية حال تعدد املدعى عليهم -صرف النظر عن الدعوى لعدم االختصاص املكاني .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"‫رقم الصك‪ 34377323 :‬تاريخه‪1434/12/3 :‬هـ‬\n                   ‫رقم الدعوى‪34506737 :‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n           ‫‪ 35113116‬تاريخه‪1435/1/11 :‬هـ‬\n\n\n‫اختصــاص ‪ -‬قســمة تركــة ‪ -‬مطالبــة الورثــة ببيــع ممتلــكات املــورث‬\n‫باملــزاد العلنــي وتقســيمها عليهــم‪ -‬تعــدد املدعــى عليهــم وإقامــة‬\n‫األكثريــة خــارج نطــاق اختصــاص احملكمــة‪ -‬االختصــاص للمحكمــة‬\n‫التــي يقــع يف نطاقهــا محــل إقامــة األكثريــة حــال تعــدد املدعــى‬\n   ‫عليهــم‪ -‬صــرف النظــر عــن الدعــوى لعــدم االختصــاص املكانــي ‪.‬‬\n\n\n\n\n           ‫املادة ‪ 5/34‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n‫ادعــى املدعــي وكالــة ضــد املدعــى عليهــم أصالــة ووكالــة بــأن مــورث‬\n‫موكلتــه واملدعــى عليهمــا قــد خلــف الفيــا الواقعــة ويطلــب بيعهــا‬\n‫باملــزاد العلنــي وتســليم موكلتــه نصيبهــا الشــرعي منهــا وبيــع جميــع مــا‬\n‫ميلكــه مورثهــم وال يســتطيع حتديــد ممتلكاتــه هكــذا ادعــى ‪ -‬أجــاب‬\n‫املدعــى عليــه بأنــه هــو وموكلتــه مــن ضمــن الورثــة وأن بقيــة الورثــة‬\n‫وهــم األكثريــة يقيمــون يف مدينــة الريــاض ويطلــب صــرف النظــر عــن‬\n‫الدعــوى هكــذا أجــاب ‪ -‬جــرى إفهــام املدعــي وكالــة بإقامــة الدعــوى‬\n‫يف مدينــة الريــاض أو إحالــة املعاملــة إلــى احملكمــة العامــة بالريــاض‬\n‫وذلــك لســكن األكثريــة مــن الورثــة يف الريــاض ‪ -‬أصــر املدعــي علــى‬\n\n                                                                                   ‫‪252‬‬\n\f      ‫مواصلــة نظــر دعــواه يف هــذه احملكمــة ‪ -‬بنــاء علــى املــادة ‪ 34‬مــن نظــام‬\n      ‫املرافعــات الشــرعية ونــص احلاجــة منهــا ( وإذا تعــدد املدعــى عليهــم‬\n      ‫كان االختصــاص للمحكمــة التــي يقــع يف نطاقهــا اختصاصهــا محــل‬\n      ‫إقامــة األكثريــة ) ‪ -‬وألن املــراد باألكثريــة يف هــذه املــادة األكثريــة‬\n      ‫بالرؤوس ال الســهام وذلك وفقا لالئحة اخلامســة من املادة ‪ - 34‬احلكم‬\n      ‫بصــرف النظــر لعــدم االختصــاص ‪ -‬إفهــام املدعــي بإقامــة دعــواه يف‬\n      ‫مدينــة الريــاض إن رغــب ‪ -‬قنــع املدعــى عليــه باحلكــم واعتــرض املدعــي‬\n      ‫بالئحــة ‪ -‬صــدق احلكــم مــن دائــرة األحــوال الشــخصية مبحكمــة‬\n                                                        ‫االســتئناف مبنطقــة حائــل ‪.‬‬\n\n\n\n      ‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف يــوم‬\n      ‫األربعــاء املوافــق ‪1434/11/19‬ه ـ لــدي أنــا ‪ .....‬رئيــس احملكمــة العامــة‬\n      ‫مبحافظــة بقعــاء افتتحــت اجللســة يف الســاعة احلاديــة عشــر والنصــف‬\n      ‫صباحــا للنظــر يف الدعــوى املقدمــة مــن ‪.....‬ضــد ‪.....‬وأبنــاء ‪.....‬واملقيــدة‬\n      ‫بهــذه احملكمــة برقــم ‪342567848‬يف ‪1434/11/11‬ه ـ واحملالــة‬\n      ‫لــي برقــم ‪ 34506737‬يف ‪1434/11/11‬ه ـ وقــد حضــر يف هــذه اجللســة‬\n      ‫‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬بصفتــه وكيــا‬\n      ‫عــن ‪.....‬مبوجــب الوكالــة الصــادرة مــن كتابــة العــدل الثانيــة بحائــل‬\n      ‫برقــم ‪ 28072‬يف ‪1433/7/19‬ه ـ واملخــول فيهــا بإقامــة الدعــاوى‬\n      ‫ودفعهــا واملرافعــة واملدافعــة والصلــح وادعــى علــى احلاضــر معــه يف‬\n      ‫هــذه اجللســة ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n      ‫بصفتــه وكيــا عــن ‪.....‬حــال كونــه وكيــا عــن ‪.....‬مبوجــب الوكالــة‬\n\n‫‪253‬‬\n\f‫رقــم ‪ 19‬يف ‪1433/9/20‬ه ـ والصــادرة مــن كتابــة عــدل بقعــاء وذلــك‬\n‫مبوجــب الوكالــة الصــادرة مــن كتابــة عــدل بقعــاء برقــم ‪34833471‬‬\n‫يف ‪1434/6/28‬ه ـ وقــرر املدعــي وكالــة بقولــه إن دعــواي ضــد ورثــة‬\n‫‪.....‬وهــم املذكوريــن بالصــك الصــادر مــن هــذه احملكمــة برقــم ‪2/8‬‬\n‫يف ‪1433/2/9‬ه ـ وهــم والــده ح‪ .....‬ووالدتــه ‪.....‬ويف زوجتــه ‪.....‬ويف أوالد‬\n‫البالغــن وهــم ‪...............‬و ‪..........‬ويف بنتــه القاصــرة عــن ســن البلــوغ‬\n‫والرشــد ‪.....‬املولــودة يف ‪1420/2/5‬ه ـ ال وارث لــه ســواهم ثــم ســألت‬\n‫املدعــي عــن بقيــة الورثــة فقــرر بقولــه إنهــم يســكنون يف الريــاض ويف‬\n‫جلســة أخــرى وفيهــا حضــر ‪.....‬ســعودي اجلنســية مبوجــب الســجل املدنــي‬\n‫رقــم ‪.....‬بصفتــه وكيــا عــن ‪.....‬مبوجــب الوكالــة الصــادرة مــن كتابــة‬\n‫العــدل الثانيــة بحائــل برقــم ‪ 28072‬يف ‪1433/7/19‬ه ـ واملخــول فيهــا‬\n‫بإقامــة الدعــاوى ودفعهــا واملرافعــة واملدافعــة والصلــح وحضــر حلضــوره‬\n‫املدعــى عليــه أصالــة ووكالــة ‪ .....‬ســعودي اجلنســية مبوجــب الســجل‬\n‫املدنــي رقــم ‪.....‬أصيــا عــن نفســه ووكيــا عــن ‪.....‬مبوجــب الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل بقعــاء برقــم ‪ 19‬يف ‪1433/9/20‬ه ـ واملخــول‬\n‫فيهــا باملرافعــة واملدافعــة ثــم حــرر املدعــي وكالــة دعــواه قائــا إن مورث‬\n‫املدعــى عليهــم ‪.....‬كان ميلــك حــال حياتــه الفلــة الواقعــة يف محافظــة‬\n‫بقعــاء وال أعــرف حدودهــا وال أطوالهــا وال مســاحتها وألن موكلتــي مــن‬\n‫ضمــن ورثــة ‪.....‬فإننــي أطلــب بيــع هذه الفلة باملزاد العلني وتســليم نصيب‬\n‫موكلتــي منهــا وكذلــك بيــع جميــع مــا ميلــك مــورث املدعــى عليهــم وال‬\n‫أســتطيع حتديــد ممتلكاتــه هــذه دعــواي وبســؤال املدعــى عليــه وكالــة‬\n‫عــن دعــوى املدعــي وكالــة أجــاب قائــا إننــي أنــا و موكلتــي مــن ضمــن‬\n‫الورثــة وإن بقيــة الورثــة يقيمــون يف الريــاض لــذا أطلــب صــرف النظر عن‬\n\n\n                                                                                     ‫‪254‬‬\n\f      ‫دعــوى املدعــي وكالــة هكــذا أجــاب املدعــى عليــه فجــرى منــي إفهــام‬\n      ‫املدعــي وكالــة بــأن يقيــم الدعــوى يف مدينــة الريــاض أو يتــم إحالــة هــذه‬\n      ‫املعاملــة إلــى احملكمــة العامــة بالريــاض وذلــك لســكن األكثريــة مــن‬\n      ‫الورثــة يف مدينــة الريــاض حســب إقــرار املدعــي وكالــة فأصــر علــى‬\n      ‫مواصلــة دعــواه لدينــا ثــم قــرر املدعــي وكالــة بقولــه إننــي قابلــت رئيــس‬\n      ‫احملكمــة العامــة بحائــل وذكــر لــي أن هــذه املعاملــة مــن اختصــاص‬\n      ‫قاضــي بقعــاء هكــذا قــرر املدعــي وكالــة فبنــاء علــى مــا تقــدم مــن‬\n      ‫دعــوى املدعــي وكالــة وألنــه أصــر علــى مواصلــة دعــواه لدينــا وملــا‬\n      ‫جــاء يف املــادة الرابعــة والثالثــن مــن نظــام املرافعــات الشــرعية ونــص‬\n      ‫احلاجــة منهــا (وإذا تعــدد املدعــى عليهــم كان االختصــاص للمحكمــة‬\n      ‫التــي يقــع يف نطــاق اختصاصهــا محــل إقامــة األكثريــة ) وألن املــراد‬\n      ‫باألكثريــة يف هــذه املــادة األكثريــة بالــرؤوس ال بالســهام أو احلصــص‬\n      ‫وذلــك حســب مــا جــاء يف الالئحــة التنفيذيــة مــن هــذه املــادة يف الفقــرة‬\n      ‫اخلامســة منهــا وألن املدعــي وكالــة واملدعــى عليــه أصالــة ووكالــة قــررا‬\n      ‫بقولهمــا إن بقيــة الورثــة وهــم ‪..... ..... ..... ..... ..... .....‬أوالد ‪.....‬يقيمــون‬\n      ‫يف مدينــة الريــاض فهــم األكثريــة وملــا تقــدم كلــه فقــد صرفــت النظــر‬\n      ‫عــن دعــوى املدعــي وكالــة لعــدم االختصــاص وأفهمتــه بــأن يقيــم دعــواه‬\n      ‫يف مدينــة الريــاض إن رغــب وبذلــك حكمــت وبعرضــه عليهمــا قنــع بــه‬\n      ‫املدعــى عليــه أصالــة ووكالــة ولــم يقنــع بــه املدعــي وكالــة وطلــب رفــع‬\n      ‫احلكــم إلــى محكمــة االســتئناف بحائــل بالئحــة اعتراضيــة فأفهمتــه‬\n      ‫بــأن عليــه اســتالم نســخة احلكــم بعــد إصــدار هــذا القــرار يف هــذا‬\n      ‫اليــوم املوافــق ‪1434/12/3‬ه ـ وأنــه إذا لــم يقــدم اعتراضــه خــال ثالثــن‬\n      ‫يومــا مــن هــذا التاريــخ فــإن حقــه يف االعتــراض يســقط ويكتســب‬\n\n\n‫‪255‬‬\n\f‫احلكــم القطعيــة ففهــم ذلــك واســتعد بــه حــرر يف ‪1434/12/3‬ه ـ‬\n‫احلمــد هلل وحــده والصــاة والســام علــى مــن ال نبــي بعــده وبعــد يف‬\n‫يــوم األحــد املوافــق ‪1434/12/22‬ه ـ لــدي أنــا ‪.......‬رئيــس احملكمــة‬\n‫العامــة مبحافظــة بقعــاء افتتحــت اجللســة يف الســاعة التاســعة وخمســة‬\n‫وأربعــن دقيقــة صباحــا بنــاء علــى ورود الالئحــة االعتراضيــة املقدمــة‬\n‫مــن املدعــي وكالــة واملقيــدة بهــذه احملكمــة برقــم ‪ 342831496‬يف‬\n‫‪1434/12/22‬ه ـ وقــد اطلعــت عليهــا ولــم أجــد فيهــا مــا يؤثــر علــى مــا‬\n‫حكمــت بــه وقــد جــرى التهميــش عليهــا بذلــك وأمــرت برفــع كامــل‬\n‫املعاملــة إلــى محكمــة االســتئناف بحائــل وصلــى اهلل وســلم علــى نبينــا‬\n           ‫محمــد وعلــى آلــه وصحبــه أجمعــن حــرر يف ‪1434/12/22‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد‪ ...‬فقــد اطلعنــا نحــن قضــاة دائــرة األحــوال‬\n‫الشــخصية مبحكمــة االســتئناف مبنطقــة حائــل علــى املعاملــة الــواردة‬\n‫مــن رئيــس احملكمــة العامــة مبحافظــة بقعــاء الشــيخ ‪..... /‬رفــق كتابــه‬\n‫رقــم (‪ )342567848‬وتاريــخ ‪1434/12/23‬ه ـ ‪ ،‬واملقيــدة باحملكمــة‬\n‫برقــم (‪ )342567848‬وتاريــخ ‪1434/12/26‬ه ـ ‪ ،‬املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلتــه برقــم (‪ )34377323‬وتاريــخ ‪1434/12/3‬ه ـ ‪،‬‬\n‫اخلــاص بدعــوى ‪..... /‬الوكيــل عــن ‪...../‬ضــد ‪..... /‬الوكيــل الشــرعي‬\n‫عــن ‪ .....‬بشــأن تســليمه نصيــب موكلتــه مــن فيــا تقــع يف محافظــة‬\n‫بقعــاء ميلكهــا مــورث موكلتــه ‪...../‬وقــد تضمــن الصــك حكــم فضيلته‬\n‫بصــرف النظــر عــن دعــوى املدعــي وكالــة لعــدم االختصــاص املكانــي‬\n‫‪ ،‬وبدراســة الصــك ‪ ،‬وصــورة ضبطــه‪ ،‬والالئحــة االعتراضيــة ‪ ،‬وأوراق‬\n‫املعاملــة ‪.‬قررنــا املصادقــة علــى مــا حكــم بــه فضيلتــه ‪ ،‬واهلل املوفــق ‪،‬‬\n                        ‫وصلــى اهلل علــى نبينــا محمــد و آلــه وصحبــه وســلم‪.‬‬\n\n\n                                                                                   ‫‪256‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":252,"source_page_end":256,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"ee623cf2f363ec3abc58b68eeac4e7d119827036dcbc6b82e7d70551818ba53f","normalized_text_hash":"3f1f906a9c21fde587b4efea8ffc8ae567b8ea49f3407c63ffc80d9493a25002","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p252-34377323"},{"id":"46be7d15-0cc7-51d9-b1b7-f84fc49c5355","document_type":"judgment","category":"judicial","subcategory":"general","title":"اختصاص -قسمة تركة -وفاة مورث وترك أموال -مسئول عن كل أماك املورث حال حياته ومتصرف فيها بعد وفاته (املدعى عليه) -مطالبة بإلزام املدعى عليه باإلفصاح عن جميع ما لديه من أوراق ومستندات خاصة بتركة املورث -دفع بعدم االختصاص وانعقاد االختصاص للقاضي مصدر احلكم يف ذات الدعوى -تدافع يف االختصاص -صرف النظر عن الدعوى لعدم االختصاص -بعث املعاملة حملكمة الاستئناف لتدقيق احلكم .","document_number":"34379338","case_number":"34260050","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة مبحافظة جدة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/12/16","year":"1434","subject":"اختصاص -قسمة تركة -وفاة مورث وترك أموال -مسئول عن كل أماك املورث حال حياته ومتصرف فيها بعد وفاته (املدعى عليه) -مطالبة بإلزام املدعى عليه باإلفصاح عن جميع ما لديه من أوراق ومستندات خاصة بتركة املورث -دفع بعدم االختصاص وانعقاد االختصاص للقاضي مصدر احلكم يف ذات الدعوى -تدافع يف االختصاص -صرف النظر عن الدعوى لعدم االختصاص -بعث املعاملة حملكمة الاستئناف لتدقيق احلكم .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫رقم الصك‪ 34379338 :‬تاريخه‪1434/12/16 :‬هـ‬\n                          ‫رقم الدعوى‪34260050 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 35199155‬تاريخه‪1435/1/17 :‬هـ‬\n\n\n       ‫اختصــاص ‪ -‬قســمة تركــة ‪ -‬وفــاة مــورث وتــرك أمــوال‪ -‬مســئول عــن‬\n       ‫كل أمــاك املــورث حــال حياتــه ومتصــرف فيهــا بعــد وفاتــه (املدعــى‬\n       ‫عليــه)‪ -‬مطالبــة بإلــزام املدعــى عليــه باإلفصــاح عــن جميــع مــا لديــه‬\n       ‫مــن أوراق ومســتندات خاصــة بتركــة املــورث‪ -‬دفــع بعــدم االختصــاص‬\n       ‫وانعقــاد االختصــاص للقاضــي مصــدر احلكــم يف ذات الدعــوى‪ -‬تدافــع‬\n       ‫يف االختصــاص‪ -‬صــرف النظــر عــن الدعــوى لعــدم االختصــاص‪ -‬بعــث‬\n                                   ‫املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم ‪.‬‬\n\n\n\n\n            ‫‪ .1‬املادة ‪ 7-5/11‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n              ‫‪ .2‬املادة ‪ 2/71‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n            ‫‪ .3‬املادة ‪ 2-1/74‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n\n\n\n\n       ‫ادعــت املدعيتــان ضــد املدعــى عليــه بــأن مورثهــم خلــف تركــة عبــارة‬\n       ‫عــن أمــوال نقديــة وعقــارات ال يعلمــان عنهــا شــيئ ًا واملدعــى عليــه هــو‬\n       ‫املســؤول عــن كل أمــاك املــورث يف حــال حياتــه واملتصــرف فيهــا‬\n       ‫بعــد وفاتــه وقــد تقدمتــا بدعــوى ضــده لــدى قــاض آخــر باحملكمــة‬\n       ‫يطالبــون فيهــا ببعــض مــا تصــرف فيــه مــن التركــة وصــدر بذلــك‬\n\n‫‪257‬‬\n\f‫حكــم ويطلبــان إلــزام املدعــى عليــه باإلفصــاح عــن جميــع مــا لديــه مــن‬\n‫مســتندات ممــا يخــص التركــة ومخاطبــة هيئــة ســوق املــال ومؤسســة‬\n‫النقــد لالستفســار عــن أمــوال املــورث ونحوهــا هكــذا ادعتــا ‪ -‬أجــاب‬\n‫املدعــى عليــه بعــدم اختصــاص فضيلــة ناظــر القضيــة وأن الدعــوى مــن‬\n‫اختصــاص فضيلــة مصــدر احلكــم الســابق ‪ -‬جــرى إفهــام املدعيتــن‬\n‫بــأن املختــص بنظرهــا هــو مصــدر احلكــم الســابق ألن هــذه الدعــوى‬\n‫ناشــئة عنهــا ‪ -‬وبنــاء علــى املــادة ‪ 7/11‬مــن نظــام املرافعــات الشــرعية‬\n‫جــرى بعــث املعاملــة للقاضــي املختــص ‪ -‬عــادت املعاملــة مــن مصــدر‬\n‫احلكــم الســابق باخلطــاب املتضمــن بــأن الدعــوى الســابقة كانــت قبــل‬\n‫وفــاة مورثهــم وهــي طلــب كــف يــد املدعــى عليــه وأمــا هــذه الدعــوى‬\n‫فهــي بعــد وفاتــه وهــي طلــب قســمة تركــة ‪ -‬ومبــا أن التدافــع قــد وقــع‬\n‫يف االختصــاص بنظــر الدعــوى ‪ -‬وبنــاء علــى املــادة ‪ 7/11‬واملــادة ‪71‬‬\n‫واملــادة ‪ 2/71‬واملــادة ‪ 74‬مــن نظــام املرافعــات الشــرعية ‪ -‬احلكــم‬\n‫بصــرف النظــر عــن الدعــوى لعــدم االختصــاص وأن االختصــاص منعقــد‬\n‫لفضيلــة مصــدر احلكــم الســابق ‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة‬\n            ‫السادســة مبحكمــة االســتئناف مبنطقــة مكــة املكرمــة ‪.‬‬\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬القاضــي يف احملكمــة العامــة‬\n‫مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس‬\n‫احملكمــة العامــة مبحافظــة جــدة برقــم ‪ 34260050‬وتاريــخ‬\n‫‪1434/06/06‬ه ـ املقيــدة باحملكمــة برقــم ‪ 341368255‬وتاريــخ‬\n‫‪1434/06/06‬ه ـ ففــي يــوم اخلميــس املوافــق ‪1434/08/25‬ه ـ افتتحــت‬\n\n                                                                                  ‫‪258‬‬\n\f      ‫اجل ــلسة الســاعة ‪ 09 : 30‬وفيهــا حضــر كل مــن ‪.....‬ســعودية اجلنســية‬\n      ‫مبوجــب الســجل املدنــي رقــم ‪.....‬و‪ .....‬ســعودية اجلنســية مبوجــب الســجل‬\n      ‫املدنــي رقــم ‪.....‬وادعتــا علــى احلاضــر معهمــا ‪.....‬ســعودي اجلنســية مبوجب‬\n      ‫الســجل املدنــي رقــم ‪.....‬قائلتــن ‪ :‬لقــد تــويف مورثنــا ‪.....‬يف ‪1433/8/5‬ه ـ‬\n      ‫وانحصــر ورثتــه يف أوالده البالغــن‪ ..... ..... ..... ..... ..... ..... ..... .....‬ال‬\n      ‫وارث لــه ســواهم مبوجــب صــك حصــر الورثــة الصــادر مــن هــذه‬\n      ‫احملكمــة برقــم ‪ 345434‬وتاريــخ ‪1434/1/7‬ه ـ ‪ ،‬وقــد خلــف تركــة ‪،‬‬\n      ‫عبــارة عــن أمــوال نقديــة وعقــارات ال نعلــم عنهــا شــيئا ‪ ،‬واملدعــى عليــه‬\n      ‫هــو مــن كان املســؤول عــن كل أمــاك املــورث يف حــال حياتــه وهــو‬\n      ‫املتصــرف فيهــا بعــد وفاتــه ‪ ،‬وقــد تقدمنــا بدعــوى ضــد املدعــى عليــه‬\n      ‫لــدى القاضــي بهــذه احملكمــة الشــيخ ‪.....‬باملكتــب القضائــي رقــم ‪17‬‬\n      ‫واملقيــدة لديــه برقــم ‪ 32463940‬وتاريــخ ‪1432/4/29‬ه ـ نطالــب فيهــا‬\n      ‫املدعــى عليــه ببعــض مــا تصــرف فيــه مــن تركــة املــورث حــال حياتــه ‪،‬‬\n      ‫وصــدر بهــا الصــك رقــم ‪ 34223580‬وتاريــخ ‪1434/5/27‬ه ـ والقاضــي‬\n      ‫بصــرف النظــر عــن دعوانــا بعــد أن حلــف املدعــى عليــه علــى إنكارها ‪،‬‬\n      ‫لــذا نطلــب إلــزام املدعــى عليــه باإلفصــاح عــن جميــع مــا لديــه مــن أوراق‬\n      ‫ومســتندات وغيرهــا ممــا يخــص تركــة املــورث ‪ ،‬ومخاطبــة مؤسســة‬\n      ‫النقــد وهيئــة ســوق املــال لالستفســار عــن جميــع مــا للمــورث مــن أمــوال‬\n      ‫ونحوهــا ‪ ،‬ومــن ثــم تســليمنا نصيبنــا مــن تركــة مورثنــا ‪ .‬هــذه دعــواي‪.‬‬\n      ‫وبعرضــه علــى املدعــى عليــه قــال ‪ :‬أدفــع بعــدم اختصــاص فضيلتكــم‬\n      ‫وأن االختصــاص منعقــد للقاضــي ‪ .....‬ملــا ورد يف دعــوى املدعيتــن ‪.‬‬\n      ‫فأفهمــت املدعيتــن بــأن دعــوى التركــة تتوجــه ضــد جميــع الورثــة ‪،‬‬\n      ‫ويكــون املدعــى عليــه مــن بينهــم ملطالبتــه شــخصيا مبــا تدعيــان بأنــه‬\n\n\n‫‪259‬‬\n\f‫بحوزتــه ‪ ،‬كمــا أن هــذه الدعــوى تعتبــر ناشــئة عــن حكــم القاضــي‬\n‫الشــيخ ‪ ،.....‬فباحلكــم انحصــرت دعــوى املدعيتــن ملــا يخــص نصيبهمــا‬\n‫مــن تركــة املــورث ملــا لــم يتضمنــه ذلــك احلكــم ‪ ،‬وذلــك بنــاء علــى املــادة‬\n‫(‪ )7/11‬مــن نظــام املرافعــات الشــرعية ‪ ،‬ونصهــا (كل دعــوى نشــأت‬\n‫عــن حكــم يف قضيــة ســابقة ‪ ،‬فينظرهــا مصــدر احلكــم الســابق ‪،‬‬\n‫إذا كان علــى رأس العمــل يف احملكمــة نفســها ‪ ،‬وكانــت مشــمولة‬\n‫بواليتــه ‪ .‬وذلــك كاحلكــم بصــرف النظــر لتوجــه الدعــوى علــى مــن‬\n‫بيــده العــن ‪ ،‬أو احلكــم ببطــان عقــد ‪ ،‬أو تصحيحــه ‪ ،‬أو انتفائــه‬\n‫‪ ،‬أو ثبوتــه ‪ ،‬أو مطالبــة احملامــي بأجرتــه) كمــا أن هــذه الدعــوى‬\n‫لهــا ارتبــاط بتلــك الدعــوى التــي ســبق احلكــم فيهــا ‪ ،‬وتكــون أيضــا‬\n‫مــن اختصــاص القاضــي ‪.....‬بنــاء علــى املــادة (‪ )71‬مــن ذات النظــام ‪،‬‬\n‫ونصهــا (الدفــع ببطــان صحيفــة الدعــوى أو بعــدم االختصــاص احمللــي‬\n‫أو بإحالــة الدعــوى إلــى محكمــة أخــرى لقيــام النــزاع ذاتــه أمامهــا أو‬\n‫لقيــام دعــوى أخــرى مرتبطــة بهــا يجــب إبــداؤه قبــل أي طلــب أو دفــاع‬\n‫يف الدعــوى ‪ ،‬وإال ســقط احلــق فيمــا لــم يبــد منهــا) والفقــرة الثانيــة مــن‬\n‫الئحتهــا التنفيذيــة ‪ ،‬ونصهــا (االرتبــاط يف هــذه املــادة هــو‪ :‬اتصــال‬\n‫الدعــوى الالحقــة بالســابقة يف املوضــوع أو الســبب وال يلــزم احتادهمــا‬\n‫يف املقــدار) ‪ ،‬لــذا فقــد قــررت إحالــة هــذه الدعــوى للقاضــي املختــص‬\n‫الشــيخ ‪.....‬باملكتــب القضائــي رقــم ‪ ...‬بنــاء علــى املــادة ‪ 7/11‬مــن نظــام‬\n‫املرافعــات الشــرعية ‪ ،‬كــون هــذه الدعــوى ناشــئة عــن احلكــم الصــادر‬\n‫منــه بالصــك رقــم ‪ 34223580‬وتاريــخ ‪1434/5/27‬ه ـ ‪ .‬ثــم رفعــت‬\n‫اجللســة لذلــك ‪ .‬ويف يــوم االثنــن املوافــق ‪1434/12/16‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 10 : 30‬وفيهــا عــادت لنــا املعاملــة مــن فضيلــة القاضــي‬\n\n\n                                                                                        ‫‪260‬‬\n\f      ‫‪.....‬بخطــاب فضيلتــه رقــم ‪ 341368255‬وتاريــخ ‪1434/11/6‬ه ـ املوجــه‬\n      ‫لفضيلــة رئيــس احملكمــة ‪ ،‬واملتضمــن أن (الدعــوى التــي لدينــا فقــد‬\n      ‫رفعــت قبــل وفاتــه بتاريــخ ‪1432/4/29‬ه ـ يطلــب املدعــون فيهــا كــف‬\n      ‫يــد املدعــى عليــه ‪.....‬عــن التصــرف يف أمــاك والدهــم إبــان حياتــه‬\n      ‫وكــف يــد املدعــى عليــه عــن التغريــر بوالدهــم كمــا أنــه لــم يتبــن لــي‬\n      ‫مــا ذكــره فضيلتــه مــن أن هــذه املعاملــة ناشــئة عــن احلكــم الصــادر‬\n      ‫منــا إذ إن هــذه الدعــوى «قســمة التركــة» لــم تنشــأ إال بعــد وفــاة مــورث‬\n      ‫الطرفــن ‪ ،‬وال يلــزم مــن إقامتهــا وجــود احلكــم الصــادر منــا ‪ ،‬وال يعــد‬\n      ‫احلكــم الصــادر منــا منشــئا لهــا ومبــا أن املعاملــة قــد أحيلــت حســب‬\n      ‫التوزيــع ‪ ،‬ودخلــت يف واليــة مكتــب ‪ ،.....‬لــذا آمــل بعــث املعاملــة‬\n      ‫لفضيلتــه بحكــم االختصــاص) أه ـ ‪ ،‬وحيــث مت بعــث املعاملــة لفضيلــة‬\n      ‫القاضــي ‪ .....‬الختصاصــه بنظــر هــذه الدعــوى ‪ ،‬بنــاء علــى املــادة ‪5/11‬‬\n      ‫مــن نظــام املرافعــات الشــرعية ‪ ،‬ونــص احلاجــة منهــا (إذا رفعــت القضيــة‬\n      ‫للقاضــي ‪ ،‬أو أحيلــت إليــه ‪ ،‬وهــو غيــر مختــص بهــا ‪ ،‬فيعيدهــا إلــى‬\n      ‫اجلهــة املختصــة التــي رفعتهــا) ‪ ،‬وحيــث أعــاد فضيلتــه املعاملــة لنــا لعــدم‬\n      ‫اختصاصــه بنظــر هــذه الدعــوى مبوجــب خطابــه املــدون أعــاه ‪ ،‬وحيــث‬\n      ‫وقــع تدافــع بينــي وبــن فضيلــة القاضــي ‪.....‬يف االختصــاص بنظــر هــذه‬\n      ‫الدعــوى ‪ ،‬وحيــث نصــت املــادة ‪ 1/74‬من نظام املرافعات الشــرعية على‬\n      ‫مــا يلــي (ال يحكــم القاضــي بعــدم االختصــاص إال بعــد حتقــق التدافــع)‬\n      ‫وقــد حتقــق ‪ ،‬وبنــاء علــى املــادة ‪ 2/74‬مــن ذات النظــام ‪ ،‬ونــص احلاجــة‬\n      ‫منهــا (إذا كان التدافــع بــن قضــاة احملكمــة الواحــدة ‪ ،‬أو بــن رئيــس‬\n      ‫احملكمــة وأحــد قضاتهــا ‪ ،‬أو بــن محكمتــن تابعتــن جلهــة قضائيــة‬\n      ‫واحــدة ‪ ،‬فعلــى مــن أحيلــت إليــه أو ًال ‪ ،‬ثــم أعيــدت إليــه ثانيـ ًا ولــم يقتنــع‬\n\n\n‫‪261‬‬\n\f‫باختصاصــه بهــا أن يصــدر قــرار ًا بصــرف النظــر بعــدم اختصاصــه ‪،‬‬\n‫وعليــه أن يرفــع القــرار وصــورة ضبطــه وأوراق املعاملــة إلــى محكمــة‬\n‫التمييــز؛ للفصــل يف ذلــك ‪ ،‬ومــا تقــرره يلــزم العمــل بــه)‪ ،‬وحيــث إن‬\n‫حكــم فضيلــة القاضــي ‪ .....‬صــدر بعــد وفــاة املــورث ‪ -‬كمــا يتضــح‬\n‫ذلــك مــن صــك حكــم فضيلتــه يف الســطر رقــم ‪ 17‬مــن الصفحــة األولــى‬\n‫بــأن املــورث تــويف يف ‪1433/8/5‬ه ـ ‪ -‬ثــم مت الســير يف الدعــوى بعــد‬\n‫ذلــك ‪ ،‬فهــذا يعنــي أن الدعــوى مت الســير فيهــا فيمــا يخــص التركــة‪،‬‬\n‫ومت التطــرق يف تلــك الدعــوى ملــا يخــص التركــة ‪ ،‬ومت احلكــم يف تلــك‬\n‫الدعــوى مــن فضيلــة القاضــي ‪.....‬مبــا نصــه (فقــد صرفــت النظــر عــن‬\n‫دعــوى املدعــن ‪..... ..... .....‬أوالد ‪.....‬وأخليــت ســبيل املدعــى عليــه ‪.....‬‬\n‫منــه) وبذلــك يتضــح أن حكــم فضيلتــه كان بخصــوص تركــة املــورث‬\n‫‪ ،‬وقــد حكــم بصــرف النظــر عــن الدعــوى‪ ،‬وبذلــك تكــون القضيــة‬\n‫التــي لديــه وســبق أن فصــل فيهــا بحكــم ســابقة لهــذه الدعــوى التــي‬\n‫لدينــا ‪ ،‬ومــا حكــم بــه فضيلتــه يكــون فصــا فيمــا يتعلــق مبــا ادعــاه‬\n‫املدعــون فيمــا يخــص التركــة ‪ ،‬فلــو لــم يحكــم فضيلتــه بذلــك احلكــم‬\n‫‪ ،‬لــكان للمدعــن احلــق يف املطالبــة بــه ‪ ،‬وينظــر يف مطالبتهــم قضــاء ‪،‬‬\n‫ولكــن بعــد الفصــل فيهــا بحكــم مكتســب القطعيــة ‪ ،‬فليــس لقــاض‬\n‫بعــده النظــر يف ذات املطالبــة والتــي تتعلــق بالتركــة ‪ ،‬مــا لــم يتــم نقــض‬\n‫ذلــك احلكــم ‪ ،‬وحيــث نصــت املــادة ‪ 71‬مــن نظــام املرافعــات الشــرعية‬\n‫علــى مــا يلــي (الدفــع ببطــان صحيفــة الدعــوى أو بعــدم االختصــاص‬\n‫احمللــي أو بإحالــة الدعــوى إلــى محكمــة أخــرى لقيــام النــزاع ذاتــه‬\n‫أمامهــا أو لقيــام دعــوى أخــرى مرتبطــة بهــا يجــب إبــداؤه قبــل أي طلــب‬\n‫أو دفــاع يف الدعــوى ‪ ،‬وإال ســقط احلــق فيمــا لــم يبــد منهــا) ونصــت‬\n\n\n                                                                                     ‫‪262‬‬\n\f      ‫املــادة ‪ 2/71‬مــن ذات النظــام علــى مــا يلــي (االرتبــاط يف هــذه املــادة‬\n      ‫هــو‪ :‬اتصــال الدعــوى الالحقــة بالســابقة يف املوضــوع أو الســبب وال يلــزم‬\n      ‫احتادهمــا يف املقــدار) ‪ ،‬وحيــث نصــت املــادة ‪ 7/11‬من ذات النظام على‬\n      ‫مــا نــص احلاجــة منــه (كل دعــوى نشــأت عــن حكــم يف قضيــة ســابقة‬\n      ‫‪ ،‬فينظرهــا مصــدر احلكــم الســابق ‪ ،‬إذا كان علــى رأس العمــل يف‬\n      ‫احملكمــة نفســها ‪ ،‬وكانــت مشــمولة بواليتــه) وحيــث األمــر مــا ذكــر‬\n      ‫‪ ،‬فتكــون الدعــوى التــي لــدى الشــيخ ‪.....‬ســابقة للدعــوى التــي لدينــا ‪،‬‬\n      ‫والدعــوى التــي لدينــا ناشــئة عمــا حكــم به فضيلته يف الدعوى الســابقة‬\n      ‫‪ ،‬فيكــون املختــص بنظــر هــذه الدعــوى هــو فضيلــة الشــيخ ‪ ،.....‬لــذا‬\n      ‫وبنــاء علــى مــا تقــدم ‪ ،‬وبنــاء علــى املــادة ‪ 71‬واملــادة ‪ 2/71‬واملــادة ‪7/11‬‬\n      ‫واملــادة ‪ 74‬مــن نظــام املرافعــات الشــرعية فقــد حكمــت بصــرف النظــر‬\n      ‫عــن الدعــوى لعــدم االختصــاص ‪ ،‬وأن االختصــاص منعقــد لفضيلــة‬\n      ‫القاضــي بهــذه احملكمــة الشــيخ ‪.....‬باملكتــب القضائــي رقــم ‪ ....‬وبــه‬\n      ‫حكمــت ‪ .‬وقــررت بعــث املعاملــة حملكمــة االســتئناف لتدقيــق احلكــم‬\n      ‫‪ .‬وأقفلــت اجللســة الســاعة ‪ . 11 : 00‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n           ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪1434/12/16‬ه ـ‬\n      ‫احلمــد هلل ‪ ،‬والصــاة والســام علــى رســول اهلل ‪ ،‬وبعــد ‪ :‬ـ فق ــد ج ــرى‬\n      ‫م ّنــا نح ــن رئيــس واعضــاء الدائ ــرة احلقوقي ــة السادســة يف محكمــة‬\n      ‫االســتئناف مبنطقــة مك ــة املكرم ــة االطــا ُع عل ــى هــذا احلكــم‬\n      ‫الصــادر مــن فضيلــة الشــيخ ‪..... /‬القاضــي باحملكمــة العامــة مبحافظــة‬\n      ‫جــدة واملســجل بع ــدد ‪ 34379338‬وتاريــخ ‪1434/12/16‬ه ـ املتضمــن‬\n      ‫دعــوى ‪.....‬و ‪.....‬ضــد ‪ ،.....‬احملكــوم في ــه مبــا دون باطنــه ‪ ،‬وبدراس ــة‬\n      ‫احلكــم وص ــورة ضبط ــه تق ــررت املوافق ــة عل ــى احلكــم ‪ ،‬واهلل املوفــق‬\n                       ‫وصل ــى اهلل عل ــى نبينــا محمــد وعل ــى آل ــه وصحب ــه وســلم‪.‬‬\n‫‪263‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":257,"source_page_end":263,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0c06b0963aebacdde293c66dcea72c937a093f8f934c02167df30cfa814db4db","normalized_text_hash":"42dcf72e454a274eef0cb997f977b51b755ab28380f2db5017412b4bcfeb4cb0","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p257-34379338"},{"id":"a1a0350c-52f4-5837-9eb0-f78268e0930d","document_type":"judgment","category":"judicial","subcategory":"general","title":"صفة -اختصام غير ذي صفة يف الدعوى -مطالبة مببلغ يف ذمة ميت -دعوى على وكيل ليس خصم ا يصح احلكم عليه -سداد الوكيل جزء من الدين غير مبرر بإلزامه بسداد الباقي -إفهام الدائن مبطالبة الورثة مبا يف ذمة مورثهم إذا كان املورث قد خلف تركه تفي مبا هو يف ذمة املورث أو بعضه -رد دعوى لعدم توجهها .","document_number":"33466146","case_number":"33321735","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بالرياض","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/27","year":"1434","subject":"صفة -اختصام غير ذي صفة يف الدعوى -مطالبة مببلغ يف ذمة ميت -دعوى على وكيل ليس خصم ا يصح احلكم عليه -سداد الوكيل جزء من الدين غير مبرر بإلزامه بسداد الباقي -إفهام الدائن مبطالبة الورثة مبا يف ذمة مورثهم إذا كان املورث قد خلف تركه تفي مبا هو يف ذمة املورث أو بعضه -رد دعوى لعدم توجهها .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/27 :‬هـ‬\n                        ‫ُ‬                ‫َر ْق ُم َّ‬\n                           ‫الص ِّك‪33466146 :‬‬\n                          ‫َر ْق ُم الدعوى‪33321735 :‬‬\n           ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                   ‫‪ 3437996‬تاريخه‪1434/2/16 :‬هـ‬\n\n\n       ‫صفــة ‪ -‬اختصــام غيــر ذي صفــة يف الدعــوى ‪ -‬مطالبــة مببلــغ يف ذمــة‬\n       ‫ميــت ‪ -‬دعــوى علــى وكيــل ليــس خصم ـ ًا يصــح احلكــم عليــه ‪ -‬ســداد‬\n       ‫الوكيــل جــزء مــن الديــن غيــر مبــرر بإلزامــه بســداد الباقــي ‪ -‬إفهــام‬\n       ‫الدائــن مبطالبــة الورثــة مبــا يف ذمــة مورثهــم إذا كان املــورث قــد خلــف‬\n       ‫تركــه تفــي مبــا هــو يف ذمــة املــورث أو بعضــه ‪ -‬رد دعــوى لعــدم توجههــا ‪.‬‬\n\n\n\n\n       ‫مــا اســتند إليــه القاضــي مــن املبــادئ العامــة وقواعد العدالة يف تســبيب‬\n                                                                           ‫حكمه ‪.‬‬\n\n\n\n\n       ‫دعــوى املدعــي ضــد املدعــى عليــه الــذي غــاب عــن حضــور اجللســة‬\n       ‫احملــددة وقــد تبلــغ بهــا لشــخصه ومضمــون الدعــوى إن املدعــى عليــه‬\n       ‫وكيــل لورثــة أخيــه وللمدعــي يف ذمــة أخيــه املتوفــى مبلغ ـ ًا مــن املــال‬\n       ‫قــدره مائتــان وخمســون ألــف ريــال قيمــة ســيارتني وقــد وصــل مــن‬\n       ‫املتوفــى مائــة ألــف ريــال وقــد ســلم املدعــى عليــه مبلغـ ًا وقــدره خمســون‬\n       ‫ألــف ريــال ‪ -‬طلــب املدعــي احلكــم علــى وكيــل الورثــة ‪ -‬أنهــى حاكــم‬\n       ‫القضيــة حكمــه بــأن الوكيــل ليــس خصم ـ ًا يصــح احلكــم عليــه يف‬\n       ‫هــذه الدعــوى ‪ -‬وصــدر احلكــم بــرد الدعــوى وإفهــام املدعــي بــأن لــه‬\n\n‫‪271‬‬\n\f‫مطالبــة الورثــة إذا كان مورثهــم خلــف تركــة تفــي مبــا يطالــب بــه مــن‬\n‫مبلــغ أو بعضــه ‪ -‬قــرر املدعــى عــدم القناعــة ‪ -‬صــدر قــرار محكمــة‬\n                          ‫االســتئناف بالريــاض باملصادقــة علــى احلكــم ‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد لــدي أنــا ‪ .....‬املــازم القضائــي واملكلــف بعمــل‬\n‫املكتــب القضائــي اخلامــس باحملكمــة العامــة بالريــاض وبنــاء علــى‬\n‫املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض‬\n‫املساعد برقم ‪ 33321735‬وتاريخ ‪1433/05/09‬هـ املقيدة باحملكمة‬\n‫برقــم ‪ 33872736‬وتاريــخ ‪ 1433/05/09‬ه ـ ففــي يــوم األربعــاء املوافــق‬\n‫‪1433/07/09‬ه ـ فتحــت اجللســة وفيهــا حضــر ‪ .....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬ولــم يحضــر املدعــى عليــه وال وكيــل‬\n‫عنــه ولــم يــرد منــه عــذر وقــد وردتنــا إفــادة احملضريــن أنــه جــرى تســليم‬\n‫صــورة مــن البــاغ ألخــت املدعــى عليــه وقال املدعي أطلــب حتديد موعد‬\n‫جديــد لتبليــغ املدعــى عليــه وعليــه رفعــت اجللســة ثــم يف جلســة أخــرى‬\n‫يــوم اإلثنــن املوافــق ‪1433/08/26‬ه ـ لــدي أنــا‪ .....‬القاضــي املنــدوب‬\n‫يف احملكمــة العامــة بالريــاض واملكلــف بالعمــل باملكتــب القضائــي‬\n‫اخلامــس بنــاء علــى خطــاب تكليــف رئيــس احملكمــة العامــة بالريــاض‬\n‫املســاعد رقــم ‪ 331441862‬يف تاريــخ ‪1433/07/30‬ه ـ فتحــت اجللســة‬\n‫وفيهــا حضــر املدعــي ولــم يحضــر املدعــى عليــه وال وكيــل عنــه وقــد‬\n‫وردتنــا إفــادة احملضــر املتضمنــة أنــه مت مقابلــة املدعــى عليــه وتعريفــه‬\n‫أنــي موظــف احملكمــة وأن معــي خطــاب تبليــغ أنكــر معرفتــه بــه ومت‬\n‫طلــب الهويــة ورفــض إبرازهــا وذلــك للتأكــد وحيــث تبلــغ املدعــى عليــه‬\n\n                                                                                      ‫‪272‬‬\n\f      ‫شــخصيا وبنــاء علــى املــادة اخلامســة واخلمســن مــن نظــام املرافعــات‬\n      ‫الشــرعية قــررت الســير يف الدعــوى وبســؤال املدعــي عــن دعــواه قــال إن‬\n      ‫املدعــى عليــه وكيــا لورثــة أخيه ولي يف ذمة املتوفى مبلغ وقدره مائتان‬\n      ‫وخمســون ألــف ريــال قيمــة ســيارتني األولــى ‪ .....‬موديــل ‪ .....‬والثانيــة ‪.....‬‬\n      ‫موديــل ‪ .....‬وقــد وصــل مــن املتوفــى مائــة ألــف ريــال وبقــي يف ذمتــه مبلــغ‬\n      ‫وقــدره مائــة وخمســون ألــف ريــال وقــد ســلمني املدعــى عليــه مبلــغ وقــدره‬\n      ‫خمســون ألــف ريــال وقــد تبقــى يف ذمــة املتوفــى مبلــغ وقــدره مائــة ألــف‬\n      ‫ريــال أطلــب احلكــم علــى املدعــى عليــه بصفتــه وكيــا للورثــة بتســديد‬\n      ‫باقــي املبلــغ وقــدره مائــة وخمســون ألــف ريــال وبســؤال املدعي عــن بيناته‬\n      ‫قــال لــدي شــهود ومســتعد بإحضارهــم ولــدي شــيكات يف املبلــغ املتبقــي‬\n      ‫وعليــه رفعــت اجللســة إلبــاغ املدعــى عليــه باحلضــور لدينــا ثــم يف جلســة‬\n      ‫أخــرى يف يــوم الســبت املوافق‪1433/11/27‬ه ـ لــدي أنــا ‪ .....‬القاضــي يف‬\n      ‫احملكمــة العامــة بالريــاض فتحــت اجللســة وفيهــا حضــر املدعــي ولــم‬\n      ‫يحضــر املدعــى عليــه وقــد وردتنــي ورقــة التبليــغ وقــد تضمنــت محضــرا‬\n      ‫بأنــه مت االنتقــال ملنــزل املدعــى عليــه ولــم يجــدوه ورفــض أهلــه اســتالم‬\n      ‫اخلطــاب وقــد جــرى االطــاع علــى مــا ســبق ضبطــه مــن الدعــوى وقــد‬\n      ‫قــرر املدعــي أنــه ال يطلــب ســوى احلكــم علــى الوكيــل ال الورثــة ومصــر‬\n      ‫علــى ذلــك عليــه وحيــث أن الوكيــل ليــس خصمــا يصــح احلكــم عليــه‬\n      ‫يف هــذه الدعــوى بدفــع املبلــغ املطالــب بدفعــه علــى الوجــه الــذي تضمنتــه‬\n      ‫الدعــوى لــذا فقــد رددت طلــب املدعــي احلكــم علــى املدعــى عليــه بدفــع‬\n      ‫املبلــغ وبذلــك حكمــت وأفهمــت أن لــه حــق إقامــة دعــواه علــى الورثــة‬\n      ‫إذا كان املــورث قــد خلــف لهــم تركــة تفــي مبــا يطلبــه مــن مبلــغ أو‬\n      ‫بعضــه وبعــرض احلكــم علــى املدعــي قــرر أنــه لــم يقنــع وأفهمتــه ب ــأن‬\n\n\n‫‪273‬‬\n\f‫سيســلم نســخة مــن صــك احلكــم لتقــدمي اعتراضــه عليــه هــذا اليــوم وأن‬\n‫لــه مهلــة ثالثــن يومــا مــن هــذا التاريــخ وإذا لــم يقــدم اعتراضــه خاللهــا‬\n‫فــإن حقــه يف االعتــراض يســقط ويكتســب احلكــم القطعيــة وبــاهلل‬\n‫التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪.‬‬\n                                                  ‫حــرر يف ‪1433/11/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد ويف يــوم الثالثــاء ‪1434/03/10‬ه ـ لــدي أنــا ‪.....‬‬\n‫القاضــي باحملكمــة العامــة بالريــاض افتتحــت اجللســة وكانــت املعاملــة‬\n‫قــد عــادت مــن محكمــة االســتئناف بالريــاض برقــم ‪ 34334213‬يف‬\n‫‪1434/02/25‬ه ـ وقــد دون علــى ظهــر الصــك الصــادر يف القضيــة مــا‬\n                                                                           ‫نصــه ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا علــى هــذا الصــك رقــم ‪33466146‬‬\n‫يف ‪1433/11/27‬ه ـ الصــادر مــن فضيلــة القاضــي باحملكمــة‬\n‫العامــة بالريــاض الشــيخ ‪ .....‬وأصدرنــا القــرار رقــم ‪ 3437996‬يف‬\n‫‪1434/02/16‬ه ـ املتضمــن املصادقــة علــى احلكــم قاضــي اســتئناف‬\n‫‪ .....‬ختمــه وتوقيعــه قاضــي اســتئناف ‪ .....‬ختمــه وتوقيعــه رئيــس الدائــرة‬\n‫ختمــه وتوقيعــه وللبيــان حــرر واهلل املوفــق حــرر يف ‪1434/03/10‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد ‪ ...‬فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة‬\n‫لتمييــز القضايــا احلقوقيــة مبحكمــة االســتئناف بالريــاض علــى املعاملــة‬\n‫الــواردة لنــا مــن فضيلــة رئيــس احملكمــة العامــة بالريــاض املســاعد‬\n‫باخلطــاب رقــم ‪ 33872736‬وتاريــخ ‪1434/2/2‬ه ـ املرفــق بهــا الصــك‬\n‫الصــادر مــن فضيلــة القاضــي باحملكمــة الشــيخ‪ .....‬برقــم ‪ .....‬وتاريــخ‬\n‫‪1433/11/27‬ه ـ بشــأن الدعــوى املقامــة مــن ‪ .....‬ضــد ‪ .....‬وبدراســة‬\n‫الصــك وصــورة ضبطــه وأوراق املعاملــة تقــرر الدائــرة املصادقــة علــى‬\n‫احلكــم ‪ .‬واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبه وســلم‪.‬‬\n                                                                                      ‫‪274‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":271,"source_page_end":274,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"38eb1f6a99caf34d776ccfe45bb4f6f9108b89e7a25615128564eb09a807121a","normalized_text_hash":"1e1e87130e231c34d0e2846871e34b85777143ef8358b805627971117dec95bc","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p271-33466146"},{"id":"01fccc63-fa14-5407-a174-d12452600016","document_type":"judgment","category":"judicial","subcategory":"general","title":"استرداد -مطالبة برد شيك لإلفراغ والتزوير -األصل أن صاحب الشيك هو املسؤول عن كتابة بياناته -إقرار املدعى عليه بتعبئة بيانات الشيك -مما يؤثر يف سامة الشيك مشاركة عنصر خارجي باستحقاقه -مصادقة طريف الدعوى عليها -وقف احلكم يف موضوع الدعوى لتعلقه بالفصل يف قضية أخرى .","document_number":"33445659","case_number":"32608189","judgment_number":null,"decision_number":null,"circular_number":null,"court":null,"circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1433/11/3","year":"1434","subject":"استرداد -مطالبة برد شيك لإلفراغ والتزوير -األصل أن صاحب الشيك هو املسؤول عن كتابة بياناته -إقرار املدعى عليه بتعبئة بيانات الشيك -مما يؤثر يف سامة الشيك مشاركة عنصر خارجي باستحقاقه -مصادقة طريف الدعوى عليها -وقف احلكم يف موضوع الدعوى لتعلقه بالفصل يف قضية أخرى .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"      ‫تاريخه‪1433/11/3 :‬هـ‬\n                       ‫ُ‬                ‫َر ْق ُم َّ‬\n                          ‫الص ِّك‪33445659 :‬‬\n                         ‫َر ْق ُم الدعوى‪32608189 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n                  ‫‪ 3419448‬تاريخه‪1434/1/21 :‬هـ‬\n\n\n      ‫اســترداد ‪ -‬مطالبــة بــرد شــيك لإلفــراغ والتزويــر ‪ -‬األصــل أن صاحــب‬\n      ‫الشــيك هــو املســؤول عــن كتابــة بياناتــه ‪ -‬إقــرار املدعــى عليــه بتعبئــة‬\n      ‫بيانــات الشــيك ‪ -‬ممــا يؤثــر يف ســامة الشــيك مشــاركة عنصــر‬\n      ‫خارجــي باســتحقاقه ‪ -‬مصادقــة طــريف الدعــوى عليهــا ‪ -‬وقــف احلكــم‬\n                     ‫يف موضــوع الدعــوى لتعلقــه بالفصــل يف قضيــة أخــرى ‪.‬‬\n\n\n\n\n                     ‫‪1 .1‬الفقرة (أ) من املادة ‪ 31‬من نظام املرافعات الشرعية‪.‬‬\n                 ‫‪ 6/2.312 .2‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n              ‫‪ 2-1/3.833 .3‬من نظام املرافعات الشرعية والئحته التنفيذية‪.‬‬\n                ‫‪4 .4‬قرار اللجنة القانونية بوزارة التجارة رقم ‪ 90‬لعام ‪1406‬هـ‪.‬‬\n\n\n\n\n      ‫ادعــى املدعــي وكالــة ضــد املدعــى عليــه وكالــة بــأن مــوكل املدعــى‬\n      ‫عليــه أخــذ مــن موكلــه شــيك ًا برقــم ‪ ....‬يف ‪1432/8/20‬ه ـ بقيمــة‬\n      ‫عشــرين مليــون ريــال بطريقــة غيــر مشــروعة مســتغال ثقــة موكلــه بــه‬\n      ‫حيــث ســلمه شــيك ًا فارغ ـ ًا وقــام املدعــى عليــه بتعبئــة بينــات الشــيك‬\n      ‫زاعم ـ ًا بيــع أربــع وعشــرين قطعــة أرض بحــي ‪ .........‬علــى موكلــه‬\n      ‫وهــذا لــم يتــم ويطلــب إلــزام املدعــى عليــه بــرد الشــيك املذكــور‬\n‫‪281‬‬\n\f‫فــور ًا هكــذا ادعــى ‪ -‬أجــاب املدعــى عليــه بــأن مــا ذكــره املدعــي‬\n‫يف دعــواه غيــر صحيــح وملوكلــه شــكوى يف الشــرطة ويوجــد اتفــاق‬\n‫بــن موكلــه ومــوكل املدعــي بخصــوص قطــع األراضــي التــي يف حــي‬\n‫‪ .........‬حيــث قــام مــوكل املدعــي ببيعهــا علــى أحــد األشــخاص وقــد‬\n‫اســتلم املبلــغ يف كتابــة العــدل مبوجــب شــيك مصــدق باســم مــوكل‬\n‫املدعــي واألراضــي باســم شــقيق مــوكل املدعــي وقــد مت بيــع األراضــي‬\n‫بعلمــه مــن قبــل موكليــه وهمــا مــوكل املدعــي ومــوكل املدعــى عليــه‬\n‫وصــادق علــى اســتالم الشــيك وأن كتابــة الشــيك كان برضــا مــوكل‬\n‫املدعــي وتوقيعــه وأن املبلــغ الــذي يف الشــيك ال يخــص موكلــه وحــده‬\n‫بــل شــريكه شــقيق مــوكل املدعــي ‪ -‬وبنــاء علــى الفقــرة (أ) مــن املــادة‬\n‫‪ 31‬مــن نظــام املرافعــات الشــرعية والالئحــة السادســة مــن ذات املــادة‪-‬‬\n‫وحيــث أنكــر املدعــى عليــه وكالــة بــأن موكلــه أخــذ الشــيك عــن‬\n‫طريــق احليلــة وأقــر بكتابــة موكلــه لبينــات الشــيك وأنــه كان مبوافقــة‬\n‫مــوكل املدعــي ومبــا أن املدعــي وكالــة أنكــر ذلــك ومبــا أن مبلــغ‬\n‫الشــيك كبيــر جــد ًا وكتابتــه مــن قبــل املســتفيد يضعــف جانبــه ومبــا‬\n‫أن األصــل يف مثــل ذلــك أن صاحــب الشــيك هــو املســؤول عــن كتابــة‬\n‫بياناتــه ومبــا أن املدعــى عليــه وكالــة أقــر بــأن مبلــغ الشــيك ال يختــص‬\n‫مبوكلــه ويشــاركه فيــه عنصــر خارجــي وهــو أخ املدعــي وذلــك ممــا‬\n‫يقــدح يف ســامة الشــيك مبوجــب قــرار اللجنــة القانونيــة بــوزارة التجــارة‬\n‫رقــم ‪ 90‬لعــام ‪1406‬ه ومبــا أن هــذا الشــيك يعــد قرينــة علــى وجــود‬\n‫تعامــات بــن طــريف الدعــوى وحفظ ـ ًا حلــق املدعــى عليــه أصالــة وبنــاء‬\n‫علــى املــادة ‪ 1/ 83‬مــن نظــام املرافعــات الشــرعية والئحتــه ‪ -‬ملــا تقــدم‬\n‫صــدر احلكــم مبــا يلــي ‪ :‬أوال‪ :‬األمــر بوقــف احلكــم وتعليقــه يف موضــوع‬\n\n\n                                                                                   ‫‪282‬‬\n\f      ‫هــذه الدعــوى لتعلقــه بالفصــل يف القضيــة املاليــة التــي بينهمــا ثاني ـاً‪:‬‬\n      ‫إفهــام الطرفــن بــأن نظــر قضيــة املوضــوع األصلــي يف احلــق املالــي ملبلــغ‬\n      ‫الشــيك محــل الدعــوى يكــون لــدى جهــة االختصــاص وهــي احملكمــة‬\n      ‫العامــة ‪ -‬قنــع املدعــي وكالــة باحلكــم واعتــرض املدعــى عليــه بالئحــة‬\n      ‫‪ -‬صــدق احلكــم مــن الدائــرة احلقوقيــة الثانيــة مبحكمــة االســتئناف‬\n                                                                  ‫باملنطقــة الشــرقية‪.‬‬\n\n\n\n\n      ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة احلقوقيــة‬\n      ‫الثانيــة يف محكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n      ‫مــن فضيلــة رئيــس احملكمــة اجلزائية مبحافظة االحســاء الشــيخ‪........./‬‬\n      ‫برقــم ‪ 331635185‬وتاريــخ ‪1433/12/22‬ه ـ املقيــدة لــدى احملكمــة‬\n      ‫برقــم ‪ 332263440‬وتاريــخ ‪1433/12/28‬ه ـ املرفــق بهــا الصــك‬\n      ‫الصــادر مــن فضيلتــه املســجل برقــم ‪.........‬وتاريــخ ‪1433/11/3‬ه ـ‬\n      ‫اخلــاص بدعــوى‪ ......... /‬ضــد‪ ......... /‬يف قضيــة حقوقيــة وقــد تضمــن‬\n      ‫الصــك حكــم فضيلتــه مبــا هــو مــدون ومفصــل فيــه ‪ .‬وبدراســة الصــك‬\n      ‫وصــورة ضبطــه والالئحــة االعتراضيــة وأوراق املعاملــة قررنــا املصادقــة‬\n      ‫علــى مــا أجــراه فضيلــة القاضــي واهلل املوفــق وصلــى اهلل علــى نبينــا‬\n                          ‫محمــد وآلــه وصحبــه وســلم حــرر يف ‪1434 /1/21‬هــ‪.‬‬\n      ‫اجلزئيــة‬\n         ‫ّ‬       ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪.....‬رئيــس احملكمــة‬\n      ‫باألحســاء وبنــاء علــى املعاملــة احملالــة ملكتبنــا برقــم ‪32608189‬‬\n      ‫وتاريــخ ‪ 1432/12/26‬ه ـ املقيــدة باحملكمــة برقــم ‪321635185‬‬\n      ‫وتاريــخ ‪ 1432/12/26‬ه ـ ففــي يــوم لثالثــاء تاريــخ ‪1432/1/4‬ه ـ ويف‬\n\n‫‪283‬‬\n\f‫متــام الســاعة العاشــرة وخمــس دقائــق افتتحــت اجللســة وفيهــا حضــر‬\n‫املدعــي وكالــة ‪».....‬ســعودي» بالســجل املدنــي رقــم‪ ).....( :‬بصفتــه‬\n‫وكيــا ‪.....‬ســعودي بالســجل املدنــي رقــم ‪ :‬مبوجــب صــك الوكالــة‬\n‫الصــادرة مــن كتابــة عــدل األحســاء الثانيــة رقــم (‪ )6862‬يف‬\n‫‪1432/2/22‬ه ـ اجللــد (‪ )3636‬املخولــة لــه املدافعــة واملرافعــة واملطالبــة‬\n‫واملخاصمــة واملداعــاة وإقامــة الدعــوى والــرد عليهــا وقبــول احلكــم‬\n‫واالعتــراض عليــه واإلقــرار واإلنــكار يف الدعــاوى والصلــح والتنــازل و‬\n‫حضــر حلضــوره املدعــى عليــه وكالــة ‪».....‬ســعودي» بالســجل املدنــي‬\n‫رقــم (‪ ).....‬بصفتــه وكيــا عــن ‪.....‬ســعودي «ســعودي» بالســجل املدنــي‬\n‫رقــم ‪..... :‬مبوجــب صــك الوكالــة الصــادر مــن كاتــب عــدل األحســاء‬\n‫الثانيــة رقــم (‪ )31019‬وتاريــخ ‪1432/8/9‬ه ـ اجللــد (‪ )3879‬املخولــة لــه‬\n‫املخاصمــة واملطالبــة واملرافعــة واملدافعــة وقبــول احلكــم واالعتــراض‬\n‫عليــه ويف الصلــح والتنــازل يف أي قضيــة تقــام منــه أو ضــده واإلقــرار‬\n‫واإلنــكار يف الدعــاوى فادعــى األول قائــا يف حتريــر دعــواه مبوجــب‬\n‫مــا جــاء يف صحيفــة الدعــوى التــي نصهــا مــا يلــي ‪ :‬لقــد أخــذ املدعــى‬\n‫عليــه مــن موكلــي شــيك ًا برقــم (‪ )000120‬يف ‪1432/8/20‬ه ـ بقيمــة‬\n‫ال‬\n‫عشــرين مليــون ريـ(‪ )20.000000‬ــال بطريقــة غيــر مشــروعة مســتغ ً‬\n‫ثقــة موكلــي بــه حيــث ســلمه شــيك ًا فارغـ ًا مــن الكتابــة وقــام بتعبئــة‬\n‫بيانــات الشــيك زاعم ـ ًا بيــع أربعــة وعشــرون قطعــة أرض يف حــي ‪.........‬‬\n‫علــى موكلــي وهــو األمــر الــذي لــم يتــم ‪ ،‬أطلــب إلــزام املدعــى عليــه بــرد‬\n‫حيــازة الشــيك املبــن بعاليــه إلــى موكلــي فــور ًا هــذه دعــواي ‪ .‬وبعــرض‬\n‫دعــوى املدعــي وكالــة علــى املدعــى عليــه وكالــة أجــاب بقولــه ‪ :‬مــا‬\n‫ذكــره املدعــي يف دعــواه غيــر صحيــح وموكلــي لــه دعــوى بخصــوص‬\n\n\n                                                                                       ‫‪284‬‬\n\f      ‫هــذا املوضــوع يف شــرطة املبــرز ويوجــد اتفــاق بــن موكلــي ومــوكل‬\n      ‫املدعــى عليــه ‪ .....‬بخصــوص عــدد أربعــة وعشــرين قطعــة أرض يف حــي‬\n      ‫‪ ........‬بالهفــوف قــام ببيعهــم مــوكل املدعــي ‪.....‬علــى املدعــو ‪ .....‬وقــد مت‬\n      ‫اســتالم املبلــغ يف كتابــة العــدل باألحســاء مبوجــب شــيك مصــدق باســم‬\n      ‫مــوكل املدعــي ‪.....‬علمــا بــأن هــذه األراضــي املذكــورة مملوكــة باســم‬\n      ‫شــقيق مــوكل املدعــي املدعــو ‪..... .....‬وقــد مت ذلــك بعلــم منــه بــأن هــذه‬\n      ‫األراضــي مت بيعهــا مــن قبــل موكليــه كالهمــا املدعــي أصالــة ‪.....‬‬\n      ‫وموكلــي ‪.....‬ثــم حضــر مالــك األراضــي ‪.....‬إلــى موكلــي وقــال لــه إنــك‬\n      ‫قــد بعــت األراضــي األربعــة وعشــرين قطعــة فقــال لــه موكلــي أن الــذي‬\n      ‫قــام بالبيــع هــو أخــوك ‪.....‬وهــو الــذي اســتلم الشــيك بنفســه وأعطــى‬\n      ‫موكلــي مبلــغ مليــون ونصــف كدفعــة أولــى مبوجــب شــيك ألجــل أن‬\n      ‫يســلمها ألخيــه ‪.....‬علمــا بــأن هــذا الشــيك األخيــر صــادر مــن حســاب‬\n      ‫زوجــة املدعــي أصالــة ‪.....‬باســم موكلــي ‪.....‬وقــد قــام موكلــي حــاال‬\n      ‫بصــرف هــذا الشــيك وتســليمه ل‪ .....‬علمــا بــأن موكلــي مقــر بــأن مبلــغ‬\n      ‫الشــيك ليــس لــه وحــده وأن نصــف هــذا املبلــغ وقــدره عشــرة ماليــن‬\n      ‫لشــقيق املدعــي أصالــة املدعــو ‪.........‬وموكلــي ال ينكــر ذلــك ألنــه‬\n      ‫يقصــد الوصــول إلــى احلــق وأخيــرا أطلــب مــن املدعــي حتريــر الدعــوى‬\n      ‫تفصيــا بعــد إجابتــي وأنــا مســتعد بإجابــة أخــرى مفصلــة يف ذلــك‬\n      ‫هكــذا أجــاب وبــرد إجابــة املدعــى عليــه وكالــة علــى املدعــي وكالــة‬\n      ‫قــرر بقولــه ال صحــة ملــا ذكــره املدعــى عليــه وكالــة والشــيك مــزور‬\n      ‫علــى موكلــي واملدعــى عليــه أصالــة هــو الــذي كتــب بيانــات الشــيك‬\n      ‫بنفســه ألنــه انتــزع الشــيك مــن موكلــي باحليلــة بعــد التوقيــع عليــه وقبــل‬\n      ‫كتابــة بياناتــه وبعــد أن أخــذه املدعــى عليــه أصالــة قــام بتعبئــة بياناتــه‬\n\n\n‫‪285‬‬\n\f‫بنفســه ألنــه قــال لــه إن هــذا الشــيك ال يقصــد منه شــيء ســوى أنه يقصد‬\n‫بــه ضمــان أمــام أخــو موكلــي ‪ ......‬علــى حــد كالمــه ملوكلــي وإننــي‬\n‫مســتعد بتحريــر الدعــوى مفصلــة بخصــوص هــذه األراضي وأما الشــيك‬\n‫فــا عالقــة لــه باملوضــوع وأنــا أطالــب بــه هكــذا قــرر وبعــرض ذلــك‬\n‫علــى املدعــى عليــه وكالــة قــرر بقولــه أن الشــيك محــل الدعــوى ليــس‬\n‫مــزور ًا والــذي وقــع عليــه هــو املدعــي أصالــة بنفســه بــدون أن يكتــب‬\n‫بياناتــه وبعــد توقيعــه عليــه أخــذ موكلــي هــذا الشــيك مــن املدعــي‬\n‫أصالــة برضــاه ثــم قــام موكلــي بتعبئــة بيانــات الشــيك وكتابتهــا بنفســه‬\n‫ومــن ضمــن البيانــات املبلــغ املذكــور فيــه وهــذا أمــر عــادي ألن املهــم هــو‬\n‫التوقيــع وأنــا مــا زلــت أطالــب بتفصيــل الدعــوى مــن قبــل املدعــي وكالــة‬\n‫هكــذا قــرر ‪ .‬ويف جلســة أخــرى حضــر لــدي الطرفــان وقــرر املدعــي‬\n‫وكالــة بقولــه لقــد أحضــرت مذكــرة فيهــا توضيــح ملــا طلبــه املدعــى‬\n‫عليــه وكالــة ألجــل بيــان حقيقــة املوضــوع ولكــن أفيــد فضيلتكــم بــأن‬\n‫موضــوع دعــوى موكلــي ينحصــر يف املطالبــة بالشــيك لكونــه أخــذ عــن‬\n‫طريــق احليلــة وقــد أقــر املدعــى عليــه وكالــة بــأن موكلــه هــو الــذي قــام‬\n‫بتعبئــة بيانــات الشــيك كمــا أنــه كتــب معلوماتــه بغيــر علــم موكلــي‬\n‫وقــد ذكــر مــوكل املدعــى عليــه يف كتابتــه علــى الشــيك بأنــه قيمــة‬\n‫أربعــة وعشــرين قطعــة أرض وهــو أقــر لديكــم بــأن هــذه األراضــي‬\n‫اشــتراها موكلــه مــن أخــو موكلــي ‪ ....‬وليــس مــن موكلــي ‪ ...‬هكــذا‬\n‫قــرر ثــم أبــرز هــذه املذكــرة فجــرى تصويرهــا وتســليم املدعــى عليــه‬\n‫وكالــة صــورة منهــا وإرفاقهــا باملعاملــة ثــم جــرى عــرض مــا قــرره املدعي‬\n‫وكالــة علــى املدعــى عليــه وكالــة فقــرر بقولــه ســوف أجيــب علــى ذلــك‬\n‫وعلــى مــا ذكــره املدعــي وكالــة يف مذكرتــه يف اجللســة القادمــة ويف‬\n\n\n                                                                                       ‫‪286‬‬\n\f      ‫جلســة أخــرى فيهــا حضــر املدعــي وكالــة ‪.........‬واملدعــى عليــه‬\n      ‫وكالة‪.........‬وقــرر املدعــى عليــه بقولــه احضــرت معــي إجابــة علــى‬\n      ‫مذكــرة املدعــي وكالــة التــي احضرهــا يف اجللســة املاضيــة ثــم ابرزهــا‬\n      ‫وباالطــاع عليهــا فــإذا هــي تتضمــن بنديــن األول فيــه الدفــع بــأن الشــيك‬\n      ‫صحيــح وليــس فيــه أي خطــأ شــرعي أو قانونــي والبنــد الثانــي فيــه أن‬\n      ‫الشــيك مت اســتالمه من املدعي أصالة بعد جلســه محاســبه وأن الشــيك‬\n      ‫كتــب بنفــس القلــم الــذي مت توقيعــه بــه يف وقــت واحــد وان مبلــغ الشــيك‬\n      ‫مقابــل عــدد أراضــي مــن حــي ‪ .........‬منهــا ‪ 24‬قطعــة حتمــل الصــك رقــم‬\n      ‫‪ 7/2/18‬بتاريــخ ‪1432/2/19‬ه ـ بقيمــة عشــرة ماليــن وخمســمائة‬\n      ‫واحــدى عشــر ألــف ريــال (‪ )1051100‬وان املدعــي ‪.........‬هــو الــذي قــام‬\n      ‫ببيعهمــا واســتلم الثمــن مبوجــب شــيك مصــدق رقــم (‪ )151586‬علــى‬\n      ‫‪ ...................‬بتاريــخ ‪2011/3/29‬م ثــم ذكــر قطــع أراضــي أخــرى‬\n      ‫داخلــه قيمتهــا يف هــذا الشــيك كمــا ذكــر يف هــذه الورقــة أن مــا يدعــي‬\n      ‫بــه وكيــل املدعــي بخصــوص شــراكة موكلــه معــه يف املضاربــة‬\n      ‫بالبورصــة غيــر صحيــح وأنــه ال يوجــد اتفــاق مبــرم بينهمــا ال شــفهي ًا وال‬\n      ‫خطيـ ًا وقــد مت إرفــاق هــذه الورقــة باملعاملــة وبعــد عرضهــا علــى املدعــي‬\n      ‫وكالــة طلــب صــوره منهــا ووعــد باإلجابــة عليهــا ويف جلســة أخــرى‬\n      ‫حضــر املدعــي وكالــة‪......... /‬واملدعــى عليــه وكالــة‪......... /‬وقــد أبــرز‬\n      ‫املدعــي وكالــة مذكــرة فيهــا جواب ـ ًا علــى رد املدعــى عليــه وكالــة‬\n      ‫الســابق وقــد جــاء فيهــا تأكيــد ملــا ذكــر ســابق ًا وتفصيــل عــن شــراء‬\n      ‫األراضــي املذكــورة وبيعهــا وذكــر املشــتري لهــا ‪.........‬وشــهادة مــوكل‬\n      ‫املشــتري ابنــه ‪.........‬وقــد وعــد املدعــي وكالــة باإلجابــة عليهــا ويف‬\n      ‫جلســة أخــرى حضــر املدعــي وكالــة ‪.........‬واملدعــى عليــه وكالــة ‪.........‬‬\n\n\n‫‪287‬‬\n\f‫فقــرر املدعــي عليــه وكالــة بقولــه لقــد أحضــرت معــي جواب ـ ًا علــى رد‬\n‫املدعــي وكالــة الســابق فأبــرزه و قــرر بقولــه أننــي ذكــرت يف هــذه‬\n‫الورقــة بيــان ملبلــغ الشــيك الــذي يعــد مكتمــل مــن النواحــي القانونيــة‬\n‫وقــد متــت كتابتــه بعــد جلســة محاســبة بــن موكلــي واملدعــي وتفصيــل‬\n‫مبالغــه كمــا يلــي ‪ -:‬أو ًال ‪ :‬مبلــغ قــدره عشــرة ماليــن وخمســمائة‬\n‫وإحــدى عشــر ألــف ريـ(‪ )10511000‬ــال قيمــة أربعــة وعشــرين قطعــة‬\n‫أرض يف مخطــط ‪ .........‬اشــتراها موكلــي مــن ‪.........‬أخــو ا ملدعــي‬\n‫ا باملبلــغ املذكــور ثاني ـ ًا ‪ :‬مبلــغ‬‫ا ثــم باعهــا علــى املدعــي مؤج ـ ً‬\n                                                                            ‫مؤج ـ ً‬\n‫ســتة ماليــن وخمســمائة ألــف ريـ(‪ )6500000‬ــال قيمــة اثني عشــر قطعة‬\n‫ا‬ ‫أرض يف حــي ‪ .........‬باعهــا موكلــي علــى املدعــي أصالــة ‪ .........‬مؤجـ ً‬\n‫ملــدة شــهرين أو ثالثــة كان قــدر اشــتراها موكلــي مــن ‪.........‬ثالث ـ ًا ‪:‬‬\n‫مبلــغ مليــون وســتمائة ريـ(‪ )1600000‬ــال قيمــة أربــع قطــع أراضــي يف‬\n‫ا رابعـ ًا‬‫حــي ‪ .........‬منطقــة (ب) باعهــا موكلــي علــى املدعــي ‪.........‬مؤجـ ً‬\n‫‪ :‬مبلــغ مليــون ريـ(‪ )1000000‬ــال ســددها موكلــي عــن املدعــي ‪.........‬‬\n‫بســبب رهــن قطعتــي أرض شــرق الهفــوف مملوكــة ملوكلــي رهنهــا‬\n‫املدعــي ‪.........‬عنــد املدعــو ‪ .........‬ألخــذ صكــي األرضــن املذكورتــن‬\n‫خامس ـ ًا ‪ :‬مبلــغ قــدره ثالثمائــة وتســعة وثمانــون ألــف ريـ(‪ )389000‬ــال‬\n‫عبــارة عــن ســعي وقــروض هــذا مــا تضمنتــه ورقتــي التــي قدمتهــا هكذا‬\n‫قــرر ثــم جــرى عــرض ذلــك علــى املدعــي وكالــة فقــرر بقولــه ‪ :‬إننــي‬\n‫ا ولكــن عنــدي ســؤال وهــو متــى‬        ‫ســوف أرد يف جلســة قادمــة رد ًا مفصـ ً‬\n‫متــت جلســة احملاســبة وكيــف أن املدعــى عليــه يســدد عــن موكلــي مبلــغ‬\n‫الرهــن ويرهــن أراضيــه فهــل هنــاك ســبب للعالقــة بينهمــا أم ال هكــذا‬\n‫قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالة قرر بقولــه ‪ :‬أما بخصوص‬\n\n\n                                                                                      ‫‪288‬‬\n\f      ‫جلســة احملاســبة فســوف أجيــب عنهــا يف جلســة قادمــة أمــا تســديد مبلــغ‬\n      ‫الرهــن فــأن موكلــي صديــق لوالدهــم وهــو ال يــرد لهــم قــو ًال ‪ .‬ثــم قــرر‬\n      ‫املدعــي وكالــة بقولــه ‪ :‬إن بــن موكلــي ومــوكل املدعــى عليــه جتــارة‬\n      ‫ا يف اجللســة القادمة هكذا‬           ‫يف البورصــة وســوف أجيــب عــن ذلــك مفصـ ً‬\n      ‫قــرر وحيــث األمــر مــا ذكــر وبعــد الدراســة والتأمــل فيمــا ضبــط ســابقا‬\n      ‫ً جــرى ســؤال املدعــى عليــه وكالــة هــل متــت كتابــة بيانــات الشــيك‬\n      ‫واملبلــغ املذكــور فيــه مــن قبــل موكلــك برضــي وموافقــة مــن املدعــي‬\n      ‫أصالــة فقــرر بقولــه نعــم كان ذلــك برضــي وموافقــة مــن املدعــي أصالــة‬\n      ‫هكــذا قــرر ثــم قــرر املدعــي وكالــة بقولــه ليــس صحيح ـ ًا مــا ذكــره‬\n      ‫املدعــى عليــه وكالــة مــن أن موكلــي وافــق ورضــي علــى كتابــة مبلــغ‬\n      ‫الشــيك وبياناتــه بــل إن موكلــي ال يعلــم بذلــك وقــد احتــال عليــه املدعــى‬\n      ‫عليــه يف أخــذ هــذا الشــيك وغــرر بــه هكــذا قــرر ثم جرى ســؤال املدعي‬\n      ‫عــن ذلــك فقــرر بقولــه لقــد حضــر املدعــى عليــه أصالــة ملوكلــي وطلــب‬\n      ‫مــن موكلــي شــيك ًا ألجــل أن يكــون إثبــات لــه يف قضيــة مطالبــة‬\n      ‫أخــرى بينــه وبــن أخــو موكلــي وهــو ‪ .........‬وحلــف لــه أميــان بأنــه فقــط‬\n      ‫ال يريــده إال لقصــد اإلثبــات وتأخيــر مطالبــة ‪ .........‬لــه وملــا بينهمــا مــن‬\n      ‫ثقــة وعالقــة قــام موكلــي بإخــراج الشــيك والتوقيــع عليــه وقبــل كتابــة‬\n      ‫البيانــات قــام املدعــى عليــه أصالــة بســحبه مــن موكلــي وأخــذه وقــال‬\n      ‫ســوف يتــم التفاهــم علــى ذلــك بعديــن هكــذا قــرر ثــم جــرى ســؤال‬\n      ‫املدعــي وكالــة هــل لــدى موكلــك بينــة علــى مــا ذكرتــه مــن أن املدعى‬\n      ‫عليــه أصالــة احتــال علــى موكلــك يف أخــذ الشــيك محــل الدعــوى‬\n      ‫بالطريقــة التــي ذكــر فقــرر بقولــه ســوف أراجــع موكلــي عــن ذلــك‪ .‬ويف‬\n      ‫جلســة أخــرى حضــر لــدي املدعــي وكالــه ‪.........‬واملدعــى عليــه وكالــه‬\n\n\n‫‪289‬‬\n\f‫‪ .........‬وجــرى ســؤال املدعــي وكالــه عــن بينتــه التــي وعــد بهــا يف اجللســة‬\n‫الســابقة فقــرر بقولــه أن بينــة موكلــي هــي كتابــة بيانــات الشــيك مبــا‬\n‫يف ذلــك التاريــخ واالســم واملبالــغ وســبب املبلــغ بخــط يــد املدعــى عليــه‬\n‫أصالــة حــال أنــه ال يوجــد عالقــة ســببية بــن مــا ذكر من بيانات الشــيك‬\n‫ومبلــغ الشــيك وقــد فصلــت طريقــة أخــذ الشــيك واالحتيــال يف ذلــك مــن‬\n‫قبــل املدعــي يف إجابتــي املفصلــة التــي قدمتهــا لكــم يف هــذه اجللســة‬\n‫كمــا أنــه يوجــد لــدى موكلــي شــهود اثنــان يشــهدون علــى مــا ذكرنــاه‬\n‫مــن العالقــة الســببية لوجــود عمليــات بيــع بــن الطرفــن ومســتعدين‬\n‫بإحضارهــم كمــا أن املدعــى عليــه لــم يقــدم مــا يثبــت كالمــه املرســل‬\n‫بخصــوص ســبب هــذا الشــيك مــن عقــد مبايعــة أو أي صكــوك أو‬\n‫وكاالت أو أوراق ثبوتيــه أخــرى تثبــت شــراء األراضــي أو اثبــات العالقــة‬\n‫الســببية للشــيك محــل الدعــوى ثــم أبــرز املدعــي وكاله مذكــرة إجابته‬\n‫املفصلــة علــى رد املدعــى عليــه وكالــه يف اجللســة الســابقة وبتســليم‬\n‫املدعــى عليــه وكالــه صــورة منهــا طلــب مهلــة للــرد عليهــا وقــرر بقولــه‬\n‫لــدي ســؤاالن وهمــا هــل املدعــي أصالــة فاقــد األهليــة والثانــي ملــاذا لــم‬\n‫يتخــذ إجــراء ضــد موكلــي عندمــا مت أخــذ الشــيك باحليلــة علــى حــد‬\n‫قولهــم وحســب دعواهــم يف وقتــه هكــذا قــرر وبعــرض ذلــك علــى‬\n‫املدعــي وكالــه أجــاب بقولــه أمــا بخصــوص األهليــة فــإن موكلــي وهلل‬\n‫احلمــد كامــل األهليــة وقــد تعامــل مــع املدعــى عليــه أصالــة مبوجــب مــا‬\n‫بينهمــا مــن عالقــة قدميــة جــدا منــذ مــا يقــارب عشــر ســنوات ومــا بينهمــا‬\n‫مــن ثقــة وتعامــل يف جتــارة البورصــة أمــا بخصــوص عــدم اإلبــاغ عــن‬\n‫اخــذه للشــيك باحلليــة يف وقتــه مــن موكلــي فقــد أجبــت عليــه مفصــا‬\n‫يف و قتــه هكــذا قــرر ويف جلســة أخــرى حضــر املدعــي وكالــه ‪.........‬و‬\n\n\n                                                                                       ‫‪290‬‬\n\f      ‫املدعــى عليــه وكالــه ‪ .........‬وقــرر املدعــى عليــه وكالــه بقولــه أحضــرت‬\n      ‫معــي اإلجابــة علــى رد املدعــي وكالــه يف اجللســة الســابقة فأبــرزه وقــد‬\n      ‫تضمنــت هــذه الورقــة أن الشــيك محــل الدعــوى ال جــدال يف صحتــه وأنــه‬\n      ‫مت إعطــاؤه ملوكلــه بعــد جلســة محاســبة مــع املدعــي أصالــة كمــا‬\n      ‫تضمنــت بــأن املدعــي أصالــة هــو الــذي اســتلم قيمــة أربعــة وعشــرين‬\n      ‫أرض بحي ‪ .........‬مبوجب الشــيك رقم ‪ 151586‬تاريخ ‪2011/03/29 :‬‬\n      ‫م مببلــغ قــدره خمســة ماليــن وتســعمائة ألــف ريــال كمــا اســتلم قيمــة‬\n      ‫األراضــي األخــرى املذكــورة مبوجــب شــيكات مجيــرة كمــا ذكــر يف‬\n      ‫املذكــرة الســابقة كمــا تضمنــت بــأن عــدم وجــود اتفاقيــات مكتوبــة‬\n      ‫بخصــوص شــراء املدعــي أصالــة لألراضــي األربعــة وعشــرين املذكــورة‬\n      ‫مــن موكلــه ال يــدل علــى عــدم صحــة البيــع و أن موكلــه قــد اشــترى‬\n      ‫هــذه األراضــي مــن أخــي املدعــي ‪.........‬بــدون ورقــة مبايعــة هــذه مــا‬\n      ‫تضمنتــه هــذه الورقــة وقــد مت ارفاقهــا باملعاملــة وتســليم املدعــي وكالــه‬\n      ‫نســخة منهــا و بســؤاله عنهــا قــرر بقولــه أمــا بخصــوص صحــة الشــيك‬\n      ‫فهــذا قــد أجبنــا عليــه ســابقا وهــو أنــه اذا انتفــت العالقــة الســببية مــع‬\n      ‫الشــيك ومبلــغ الشــيك تنتفــي صحتــه أمــا مــا ذكــره بخصــوص اســتالم‬\n      ‫موكلــه للشــيك محــل الدعــوى مــن موكلــي بعــد جلســة محاســبة ال‬\n      ‫صحــة لــه لعــدم وجــود مــا يثبــت هــذه احملاســبة ال ســيما و أن املبلغ كبير‬\n      ‫جــدا وهــو عشــرين مليــون أمــا بخصــوص مــا ذكــره من اســتالم موكلي‬\n      ‫للشــيك الــذي ذكــر وهــو قيمــة اربعــة وعشــرين أرض بحــي ‪ .........‬باملبلــغ‬\n      ‫الــذي ذكــر فهــذا غيــر صحيــح فــإن موكلــي لــم يشــتر مــن املدعــى‬\n      ‫عليــه هــذه األراضــي التــي ذكــر وإمنــا اســتلم مبلــغ الشــيك ألجــل أن يقــوم‬\n      ‫باملضاربــة فيــه حســب اتفــاق مســبق بينهمــا و يوجــد علــى ذلــك شــهود‬\n\n\n‫‪291‬‬\n\f‫أمــا بخصــوص مــا ذكــره مــن أن عــدم وجــود ورقــة مبايعــة ال يلغــي صحــة‬\n‫البيــع فهــذا غيــر صحيــح ألنــه ذكــر بــأن موكلــه اشــترى هــذه األراضي‬\n‫مــن أخــي موكلــي ‪.........‬بــدون ورقــة مبايعــة ألنــه مت البيــع بــن املدعــى‬\n‫عليــه وأخــي موكلــي مبوجــب شــيكات مفصلــة فيهــا أقيــام هــذه‬\n‫األراضــي ودفعاتهــا كمــا يوجــد أيضــا وكالــه شــرعية مــن املدعــى‬\n‫عليــه أصالــة مذكــور فيهــا رقــم الصــك لهــذه األراضــي كمــا أنــي‬\n‫أطلــب توجيــه ســؤال للمدعــى عليــه وكالــه وهــو مــا ســبب حضــور‬\n‫موكلــه لــدى كتابــة العــدل أثنــاء إجــراء عمليــة إفــراغ قطــع األراضــي‬\n‫األربعــة وعشــرين مــع املشــتري بــدون حضــور موكلــي ‪ .........‬وهــذا يــدل‬\n‫علــى أن البائــع لهــذه األراضــي هــو مــا لكهــا احلقيقــي املدعــى عليــه‬\n‫أصالــة ‪ .........‬هكــذا قــرر وبعــرض ذلــك علــى املدعــى عليــه وكالــه‬\n‫أجــاب قائــا أمــا مــا ذكــره املدعــي وكالــه عــن ســبب وجــود موكلــي‬\n‫لــدى كتابــة العــدل أثنــاء إفــراغ األراضــي املذكــورة والســبب هــو وجــود‬\n‫صــك قطــع األراضــي األربعــة وعشــرين يف حــوزة موكلــي فذهــب ألجــل‬\n‫أن يســلمه للمدعــي أصالــة ‪.........‬كونــه هــو املشــتري منــه لهذه األراضي‬\n‫ثــم قــام ‪.........‬املدعــي أصالــة باإلفــراغ يف هــذه األراضــي للمشــتري‬\n‫‪ .........‬واســتلم قيمتهــا مبوجــب الشــيك املذكــور أمــا بخصــوص جلســة‬\n‫احملاســبة فقــد فصلهــا موكلــي للمدعــي يف اجللســة التــي متــت بينهمــا‬\n‫وأن مــا بعــده ينهــي مــا قبلــه هكــذا قــرر ثــم قــرر املدعــي بقولــه أنــه‬\n‫يوجــد بينــه لــدى موكلــي وهــو املدعــو ‪ .........‬املشــتري لهــذه القطــع‬\n‫األراضــي بوكالتــه عــن والــده وشــهادته حاســمة يف موضــوع هــذه‬\n‫الدعوى ويف جلســة أخرى حضر املدعي أصالة ‪ .........‬ســعودي بالســجل‬\n‫املدني رقم ‪ ......... :‬واملدعي عليه أصالة ‪ .........‬ســعودي بالســجل املدني‬\n\n\n                                                                                     ‫‪292‬‬\n\f      ‫رقــم ‪ ......... :‬فجــرى عــرض الدعــوى علــى املدعــي أصالــة وقراءتهــا عليــه‬\n      ‫فقــرر مصادقتــه عليهــا كمــا جــرى عــرض إجابــة وكيــل املدعــى عليــه‬\n      ‫علــى املدعــى عليــه أصالــة وقراءتهــا عليــه فقــرر مصادقتــه عليهــا‬\n      ‫واســتثنى بقولــه إن إجابــة موكلــي علــى دعــوى املدعــي وكالــة صحيحة‬\n      ‫يف جميــع مــا ذكــره وهــي نفــس إجابتــي علــى الدعــوى مــا عــدا التوقيــع‬\n      ‫علــى الشــيك فــإن الصحيــح هــو أن توقيــع املدعــي أصالــة علــى الشــيك‬\n      ‫كان بعــد كتابــة بياناتــه مــن قبلــي فقــد كتبــت بيانات الشــيك بنفســي‬\n      ‫ثــم قــام املدعــي أصالــة بالتوقيــع علــى الشــيك بعــد ذلــك هكــذا قــرر ‪،‬‬\n      ‫ثــم قــرر املدعــي أصالــة بقولــه ال صحــة ملــا ذكــره املدعــى عليــه أصالــة‬\n      ‫فأنــا لــم أعلــم عــن مبلــغ الشــيك الــذي كتبــه املدعــي أصالــة وإمنــا وقعــت‬\n      ‫عليــه علــى بيــاض فقــط ثــم قــام املدعــى عليــه بســحبه منــي ونــزل مــن‬\n      ‫الســيارة وهــو يتصــل بالهاتــف ثــم قــال لــي جاءتــه مكاملــة بــأن والــده‬\n      ‫مريــض فذهــب بالشــيك بعــد التوقيــع عليــه علــى بيــاض هكــذا قــرر ‪،‬‬\n      ‫ثــم قــرر املدعــى عليــه أصالــة بقولــه ‪ :‬مــا ذكــره املدعــي أصالــة غيــر‬\n      ‫صحيــح و ممــا يــدل علــى صحــة كالمــي أن املدعــى عليــه لــم يقــدم‬\n      ‫شــكوى بعــد اســتالمي للشــيك بــل الذ بالفــرار خــارج البــاد ولــم يراجــع‬\n      ‫أحــد مــن قبلــه كمــا أفيدكــم بــأن املدعــي أصالــة قــال لــي ‪ :‬بــأن حقــك‬\n      ‫ثابــت ولــك أكثــر مــن هــذا املبلــغ وأنــا بلغــت إخوانــي بأننــي متنــازل‬\n      ‫مببلــغ عشــرين مليــون لــك مــن ورثــي وأن أخــوه ‪ .....‬يأخــذ حقــه مــن هــذا‬\n      ‫املبلــغ هكــذا قــرر ‪ ،‬ثــم قــرر املدعــي أصالــة بقولــه ‪ :‬مــا ذكــره املدعــى‬\n      ‫عليــه أصالــة غيــر صحيــح فلــم أقــل لــه هــذا الــكالم الــذي ذكــره مــن‬\n      ‫أننــي وعدتــه بتســليم املبلــغ الــذي ذكــر ولــم أقــل لــه بأننــي تنازلــت مــن‬\n      ‫ورثــي لــك باملبلــغ الــذي ذكــر فــكل هــذا غيــر صحيــح كمــا أن مــا‬\n\n\n‫‪293‬‬\n\f‫ذكــره مــن أننــي لــم أقــدم شــكوى بعــد اســتالم الشــيك فهــذا ألننــي لــم‬\n‫أعلــم عــن مبلــغ الشــيك وأنــا كنــت علــى ســفر ولــم أعلــم إال بعــد مــا‬\n‫ســافرت وهــو قــال لــي بــأن هــذا الشــيك ســوف يحفظــه لديــه وهــو علــى‬\n‫بيــاض ألجــل أن يطلــب مــن أخــي ‪ .........‬تأجيــل املبلــغ الــذي يطالبــه بــه‬\n‫هكــذا قــرر ‪ ،‬ثــم قــرر املدعــى عليــه أصالــة بقولــه كالم املدعــي أن‬\n‫الشــيك الــذي اعطانــي إيــاه ألجــل أخيــه ‪ .........‬غيــر صحيــح جملــة‬\n‫وتفصيــا بــل هــو حقــي وبعــد ذلــك جــرى نصــح الطرفــن وترغيبهمــا يف‬\n‫الصلــح فقــرر املدعــي أصالــة بقولــه ‪ :‬ليــس لــدي مــا نــع مــن الصلــح وأن‬\n‫بينــي وبــن املدعــى عليــه أصالــة تعامــل ســابق بخصــوص املتاجــرة يف‬\n‫البورصــة وعندنــا مكتــب وعمــال بخصــوص ذلــك وأنــا مســتعد بجلســة‬\n‫محاســبة مــع املدعــي إلطالعــه علــى احلســابات والشــيكات الســابقة‬\n‫هكــذا قــرر ‪ ،‬كمــا قــرر املدعــى عليــه أصالــة بقولــه مــا ذكــره‬\n‫املدعــي أصالــة غيــر صحيــح كمــا أننــي ليــس لــدي مانــع مــن الصلــح‬\n‫ولكــن يوجــد طــرف مهــم يف الصلــح وهــو أخــو املدعــي أصالــة ‪.........‬‬\n‫وأطلــب مــن املدعــي أصالــة إجــراء التفاهــم مــع أخيــه ‪ .........‬بخصــوص‬\n‫الصلــح لكونــه يطالبنــي مببلــغ مبوجــب شــيكات هكــذا قــرر ‪،‬‬\n‫وتأجلــت اجللســة ألجــل ذلــك ‪ ،‬ثــم قــرر املدعــي أصالــة بقوله أنني مســافر‬\n‫خــارج البــاد وال اســتطيع احلضــور إال بعــد رمضــان كمــا أن أخــي ‪.........‬‬\n‫مســافر حاليـ ًا خــارج البــاد هكــذا قــرر ويف جلســة أخــرى حضــر لــدي‬\n‫‪ « .........‬ســعودي» مبوجــب الســجل املدنــي رقــم ‪ ......... :‬بصفتــه وكيــا‬\n‫شــرعيا عــن املدعــي ‪..................‬مبوجــب الوكالــة الشــرعية الصــادرة‬\n‫مــن كتابــة عــدل األحســاء الثانيــة رقــم ‪ 33338214 :‬تاريــخ ‪:‬‬\n‫‪1433/10/25‬ه ـ واملخــول لــه فيهــا باملرافعــة واملدافعــة واإلقــرار‬\n\n\n                                                                                     ‫‪294‬‬\n\f      ‫واإلنــكار وقبــول األحــكام ونفيهــا واالعتــراض علــى األحــكام‬\n      ‫وحضــر حلضــوره املدعــى عليــه وكالــه ‪ .........‬وقــد جــرى ســؤال الطرفني‬\n      ‫هــل جــرى بــن موكليهمــا صلــح بنــاء علــى مــا مت طلبــه يف اجللســة‬\n      ‫الســابقة فقــرر الطرفــان بالوكالــة بأنــه لــم يتــم بينهمــا صلــح حتــى اآلن‬\n      ‫ـاء علــى مــا تقــدم مــن دعــوى املدعــي‬   ‫وطلبــا احلكــم يف القضيــة فبنـ ً‬\n      ‫وكالــة وإجابــة املدعــى عليــه وكالــة وحيــث إن املدعــي وكالــة يطالــب‬\n      ‫باســترداد حيــازة الشــيك محــل الدعــوى رقــم (‪ )000120‬وتاريــخ‬\n      ‫‪1432/8/2‬ه ـ املســحوب علــى (‪ ........‬فــرع ‪ ........‬شــارع الظهــران ؟‬\n      ‫االحســاء) لكونــه أخــذه منــه عــن طريــق احليلــة وبنــاء علــى الفقــرة (أ)‬\n      ‫مــن املــادة رقــم (‪ )31‬مــن نظــام املرافعــات الشــرعية واملــادة رقــم (‪)6/31‬‬\n      ‫مــن اللوائــح التنفيذيــة لنظــام املرافعــات الشــرعية وحيــث أن املدعــى‬\n      ‫عليــه وكالــة أنكــر أن موكلــه أخــذ هــذا الشــيك عــن طريــق احليلــة مــن‬\n      ‫املدعــي أصالــه كمــا أقــر بــأن موكلــه هــو الــذي قــام بكتابــة بيانــات‬\n      ‫الشــيك محــل الدعــوى ومنهــا كتابــة مبلــغ الشــيك وحيــث إن املدعــى‬\n      ‫عليــه وكالــة دفــع بــأن كتابــة مبلــغ الشــيك متــت مبوافقــة املدعــي أصالة‬\n      ‫ورضــاه وحيــث أنكــر مــوكل املدعــي موافقتــه علــى كتابــة مبلــغ‬\n      ‫الشــيك وحيــث إن مبلــغ الشــيك محــل الدعــوى كبيـ ٌـر جــد ًا وان كتابتــه‬\n      ‫مــن قبــل املســتفيد يضعــف جانبــه ال ســيما وأن مــوكل املدعــي أنكــر‬\n      ‫بــأن موكلــه ال يعلــم عــن حقيقــة املبلــغ ولــم يوافــق عليــه وحيــث أقــر‬\n      ‫املدعــى عليــه وكالــة بــأن هــذا الشــيك هــو عبــارة عــن قيمــة عــدد كبيــر‬\n      ‫مــن األراضــي التــي باعهــا موكلــه علــى املدعــي أصالــة يف عــدة‬\n      ‫مخططــات علــى فتــرات متفرقــة وحيــث إن مثــل هــذا التعامــل الكبيــر‬\n      ‫جــرت عــادت التجــار يف مثلــه مــن التوثيــق والتســجيل واإلثبــات يف‬\n\n\n‫‪295‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"5ec3c05d-25a7-5e37-b789-cd50c4e462d3","source_page_start":281,"source_page_end":295,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"288b82993408295b53fe63221bf8c32f7d18d6d23844daff7d62afb4b36d989b","normalized_text_hash":"ef0a6e4e0d65cc4710e1c567214fb636aa13c195dafe5325824c29b11a28b505","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v28-p281-33445659"}]$archive_payload$::jsonb AS data)
INSERT INTO public.legal_documents (
  id,document_type,category,subcategory,title,document_number,case_number,judgment_number,decision_number,
  circular_number,court,circuit,issuing_authority,document_date,hijri_date,year,subject,summary,facts,claims,
  reasoning,ruling,principle_text,full_text,legal_articles,source_id,source_file_id,source_page_start,
  source_page_end,original_source,acquisition_source,source_url,content_hash,normalized_text_hash,status,review_status
)
SELECT (x->>'id')::uuid,x->>'document_type',x->>'category',x->>'subcategory',x->>'title',x->>'document_number',
       x->>'case_number',x->>'judgment_number',x->>'decision_number',x->>'circular_number',x->>'court',x->>'circuit',
       x->>'issuing_authority',(x->>'document_date')::date,x->>'hijri_date',x->>'year',x->>'subject',x->>'summary',
       x->>'facts',x->>'claims',x->>'reasoning',x->>'ruling',x->>'principle_text',x->>'full_text',
       COALESCE(x->'legal_articles','[]'::jsonb),(x->>'source_id')::uuid,(x->>'source_file_id')::uuid,
       (x->>'source_page_start')::integer,(x->>'source_page_end')::integer,x->>'original_source',
       x->>'acquisition_source',x->>'source_url',x->>'content_hash',x->>'normalized_text_hash',x->>'status',x->>'review_status'
FROM payload CROSS JOIN LATERAL jsonb_array_elements(payload.data) AS x
LIMIT 25
ON CONFLICT (id) DO NOTHING;

